-- RN Master standalone MC/SATA pilot import. Source: user-provided 1000-question RN master bank.
begin;
do $$
declare r record; qid uuid; qvid uuid; optrec record; n int; keyarr text[]; kc int;
begin
for r in select * from (values
('Set31-RN-1','Management of Care','Prioritization: GI procedure unit','single_best_answer','The nurse in an endoscopy recovery area is caring for four clients. Which client should the nurse assess first?','A client 1 hour after colonoscopy with polyp removal who reports severe abdominal pain, with a rigid, distended abdomen and HR 122/min|A client after upper endoscopy who reports a mild sore throat|A client after colonoscopy who is passing gas and reports mild bloating|A client who is drowsy but arousable after moderate sedation, with stable vital signs','A','Severe pain with a rigid, distended abdomen and tachycardia after colonoscopy suggests bowel perforation, a surgical emergency. Gas, mild bloating, and a sore throat are expected.','Integrated','Management of Care'),
('Set31-RN-2','Reduction of Risk Potential','Left ventricular assist device','single_best_answer','The nurse is assessing a client with a continuous-flow left ventricular assist device (LVAD). The client has no palpable radial pulse. What should the nurse do?','Begin chest compressions immediately|Measure BP by Doppler, which reflects the mean arterial pressure, and check device flow, alarms, and perfusion|Call a code because the client is pulseless|Remove the driveline to reset the device','B','Continuous-flow LVADs produce little or no pulsatile flow, so pulses may be absent in a well-perfused client. The nurse assesses perfusion, mental status, device parameters, and Doppler MAP, often targeted around 70–90 mm Hg.','Integrated','Adult Health'),
('Set31-RN-3','Reduction of Risk Potential','Exercise stress test preparation','single_best_answer','A client is scheduled for an exercise stress test. Which instruction should the nurse include?','"Drink extra coffee the morning of the test."|"Avoid caffeine for about 24 hours, and ask your provider whether to hold medications such as beta blockers before the test."|"Eat a large meal right before the test."|"Wear dress shoes."','B','Caffeine interferes with pharmacologic stress agents, and beta blockers can blunt the heart rate response. Comfortable shoes and clothing are worn, and a light meal a few hours beforehand is usually allowed.','Integrated','Adult Health'),
('Set31-RN-4','Physiological Adaptation','Hemothorax','single_best_answer','A chest tube is inserted for a traumatic hemothorax. The initial output is 1,700 mL of blood, followed by 250 mL/hr for the next 2 hours. What does the nurse anticipate?','Clamping the chest tube to stop the bleeding|Notifying the surgeon for possible thoracotomy, and preparing blood products|Removing the chest tube|Continuing to observe for 24 hours','B','Large initial output (often more than 1,500 mL) or ongoing bleeding of about 200 mL/hr or more suggests major vascular injury that may require surgery. Clamping would trap blood in the chest.','Integrated','Adult Health'),
('Set31-RN-5','Pharmacological and Parenteral Therapies','Tiotropium','single_best_answer','A client with COPD is prescribed tiotropium by dry powder inhaler. Which instruction should the nurse include?','"Use it as a rescue inhaler during attacks."|"Use it once daily, avoid getting the powder in your eyes, and report eye pain or blurred vision."|"Swallow the capsule."|"Use it every 2 hours as needed."','B','Tiotropium is a long-acting anticholinergic maintenance drug. Powder in the eyes can precipitate narrow-angle glaucoma. Dry mouth and urinary retention are other side effects. Capsules are placed in the device, not swallowed.','Integrated','Pharmacology'),
('Set31-RN-6','Health Promotion and Maintenance','Spinal cord injury function','single_best_answer','A client with a complete C6 spinal cord injury asks what level of independence to expect. Which statement by the nurse is most accurate?','"You will be able to walk independently."|"With adaptive equipment such as wrist splints and utensil holders, you may be able to feed yourself and help with some self-care."|"You will need a ventilator for breathing."|"You won''t be able to move your arms at all."','B','At C6, shoulder movement, elbow flexion, and wrist extension are typically preserved, allowing tenodesis grasp and assisted self-care with devices. Ventilator dependence is more typical of injuries at C3 and above.','Integrated','Fundamentals'),
('Set31-RN-7','Reduction of Risk Potential','Hyperventilation and ICP','single_best_answer','A mechanically ventilated client with a traumatic brain injury has a stable ICP. What PaCO2 range does the nurse expect the team to maintain?','20–25 mm Hg (aggressive hyperventilation)|About 35–45 mm Hg (normocapnia)|50–60 mm Hg|Above 65 mm Hg','B','Routine hyperventilation causes cerebral vasoconstriction and can worsen ischemia. Brief hyperventilation is reserved for signs of impending herniation.','Integrated','Adult Health'),
('Set31-RN-8','Physiological Adaptation','Insulin in kidney failure','single_best_answer','A client with type 2 diabetes and worsening chronic kidney disease has had several episodes of hypoglycemia on the same insulin dose. What is the most likely explanation?','Increased insulin resistance|Reduced kidney clearance of insulin, which prolongs its action|Excess dietary sugar|Improved pancreatic function','B','The kidneys clear a significant portion of insulin. As kidney function declines, insulin lasts longer, and doses often need to be reduced. Some oral agents also accumulate.','Integrated','Adult Health'),
('Set31-RN-9','Physiological Adaptation','Primary adrenal insufficiency','single_best_answer','Which findings are characteristic of primary adrenal insufficiency (Addison''s disease)?','Weight gain, moon face, and hypertension|Fatigue, weight loss, darkened skin (especially in creases and gums), salt craving, and low BP|Heat intolerance and exophthalmos|Hyperglycemia and hypokalemia','B','Low cortisol and aldosterone cause hypotension, hyponatremia, hyperkalemia, and hypoglycemia. High ACTH stimulates melanocytes, causing hyperpigmentation.','Integrated','Adult Health'),
('Set31-RN-10','Health Promotion and Maintenance','Ileal resection','single_best_answer','A client with Crohn''s disease had most of the terminal ileum removed. Which long-term supplement does the nurse anticipate?','Vitamin C|Vitamin B12 by injection or another non-oral route|Iron only|Vitamin K only','B','Vitamin B12 is absorbed in the terminal ileum. Without it, clients develop B12 deficiency with anemia and neuropathy. Bile acid malabsorption can also cause diarrhea.','Integrated','Fundamentals'),
('Set31-RN-11','Physiological Adaptation','Lower GI bleeding','single_best_answer','An older adult has a sudden, painless passage of a large amount of maroon and bright red blood from the rectum. Which cause is most likely?','Peptic ulcer|Diverticular bleeding|Esophageal varices|Appendicitis','B','Diverticular bleeding is a common cause of painless lower GI hemorrhage in older adults. The nurse assesses hemodynamic status and prepares for resuscitation and colonoscopy.','Integrated','Adult Health'),
('Set31-RN-12','Pharmacological and Parenteral Therapies','Renal colic pain management','single_best_answer','A client with normal kidney function has renal colic from a ureteral stone. Which medication is commonly used first-line for pain?','Oral acetaminophen only|An NSAID such as IV ketorolac|Meperidine|No pain medication until the stone passes','B','NSAIDs reduce ureteral spasm and inflammation and are effective first-line analgesics for renal colic when kidney function allows. Opioids are added if needed.','Integrated','Pharmacology'),
('Set31-RN-13','Physiological Adaptation','Cauda equina syndrome','single_best_answer','A client with a history of lumbar disc disease reports new numbness in the groin and inner thighs, difficulty urinating, and bilateral leg weakness. What should the nurse do?','Recommend rest and heat at home|Recognize possible cauda equina syndrome and arrange emergency evaluation|Give a muscle relaxant and reassess in a week|Encourage vigorous stretching','B','Saddle anesthesia, bladder or bowel dysfunction, and bilateral leg symptoms indicate cauda equina compression, a surgical emergency. Delayed decompression can cause permanent loss of function.','Integrated','Adult Health'),
('Set31-RN-14','Pharmacological and Parenteral Therapies','Sickle cell pain management','single_best_answer','An adult in sickle cell pain crisis has a prescription for meperidine. What should the nurse do?','Administer it as prescribed|Question the prescription, since meperidine is avoided because its metabolite can cause seizures, especially with repeated doses|Give it intramuscularly every hour|Combine it with an MAOI','B','Normeperidine accumulates and lowers the seizure threshold. Opioids such as morphine or hydromorphone, often by PCA, are preferred.','Integrated','Pharmacology'),
('Set31-RN-15','Basic Care and Comfort','Pelvic radiation','single_best_answer','A client receiving radiation to the pelvis develops frequent loose stools. Which dietary recommendation should the nurse give?','"Eat more raw vegetables and bran."|"Follow a low-fiber (low-residue) diet, drink plenty of fluids, and avoid greasy and spicy foods."|"Drink large amounts of milk."|"Stop drinking fluids to reduce diarrhea."','B','Radiation enteritis causes diarrhea. Low-residue foods, hydration, and avoiding irritants help, along with prescribed antidiarrheals and skin care.','Integrated','Adult Health'),
('Set31-RN-16','Safety and Infection Control','Infection prevention for immunocompromised clients','single_best_answer','A client who recently received a kidney transplant enjoys gardening and has a cat. Which instruction should the nurse include?','"Give up all hobbies."|"Wear gloves and a mask when gardening or handling soil, and have someone else clean the litter box."|"Change the litter box yourself daily without gloves."|"Soil exposure is harmless."','B','Soil and animal waste can carry organisms such as fungi and Toxoplasma that cause serious infections in immunosuppressed clients. Precautions allow safe enjoyment of hobbies.','Integrated','Safety & Infection Control'),
('Set31-RN-17','Pharmacological and Parenteral Therapies','Valproate','single_best_answer','A client with bipolar disorder is starting valproic acid. Which symptoms should the nurse instruct the client to report immediately?','Mild weight gain|Severe abdominal pain, vomiting, jaundice, or unusual bleeding or bruising|Improved mood|Mild hair thinning','B','Valproate can cause hepatotoxicity, pancreatitis, and thrombocytopenia. It is highly teratogenic, so contraception is discussed. Liver function, platelets, and drug levels are monitored.','Integrated','Pharmacology'),
('Set31-RN-18','Health Promotion and Maintenance','Placenta previa at home','single_best_answer','A client at 30 weeks'' gestation with placenta previa and no active bleeding is discharged home. Which instruction should the nurse include?','"Resume all normal activities, including intercourse."|"Avoid intercourse and anything inserted into the vagina, and go to the hospital immediately for any bleeding or contractions."|"Use tampons for any spotting."|"Plan for a vaginal birth."','B','Pelvic rest reduces the risk of bleeding. Previa covering the cervix requires cesarean birth. Any bleeding requires urgent evaluation.','Integrated','Fundamentals'),
('Set31-RN-19','Physiological Adaptation','Splenic sequestration','single_best_answer','A 2-year-old with sickle cell disease suddenly becomes pale and lethargic. The spleen is markedly enlarged, and the child has tachycardia and hypotension. What does the nurse suspect?','Vaso-occlusive pain crisis only|Acute splenic sequestration crisis|Iron deficiency anemia|Viral gastroenteritis Case study (use for RN Questions 20–25). A 44-year-old client is admitted with tingling in the feet that began 5 days ago and has progressed to weakness in both legs and now the hips. Two weeks ago, the client had a diarrheal illness after eating undercooked chicken. Nurses'' notes, 0900: Symmetric weakness of both legs (2/5) and mild weakness of both arms (4/5). Deep tendon reflexes absent in the legs and diminished in the arms. Reports aching back and leg pain. Mild difficulty swallowing thin liquids. Alert and oriented. Vital signs over the past 4 hours: HR ranging from 48 to 128/min; BP ranging from 88/50 to 182/104 mm Hg; RR 22/min; SpO2 95% on room air. Respiratory measurements: forced vital capacity 22 mL/kg (baseline 50 mL/kg), negative inspiratory force −26 cm H2O. Lumbar puncture: elevated CSF protein with a normal white blood cell count.','B','In splenic sequestration, blood pools in the spleen, causing rapid anemia and hypovolemic shock. It requires emergency transfusion. Parents are taught to palpate the spleen.','Integrated','Adult Health'),
('Set32-RN-1','Management of Care','Prioritization: pediatric ED','single_best_answer','The pediatric emergency nurse is triaging four children. Which child should the nurse see first?','A 2-year-old with a barking cough, stridor at rest, and suprasternal retractions|A 4-year-old with a runny nose and a temperature of 100.2°F (37.9°C)|A 6-year-old with an ear infection who is playing in the waiting room|A 9-year-old with a forearm laceration that has stopped bleeding','A','Stridor at rest with retractions indicates moderate to severe upper airway obstruction from croup, which requires immediate treatment. The other children are stable.','Integrated','Management of Care'),
('Set32-RN-2','Pharmacological and Parenteral Therapies','Croup treatment','single_best_answer','A child with moderate to severe croup receives nebulized racemic epinephrine and oral dexamethasone. Which action is most important after the epinephrine treatment?','Discharge the child immediately once stridor improves|Observe the child for at least 2–4 hours for a return of symptoms as the epinephrine wears off|Give a second dose of dexamethasone every hour|Place the child flat to rest','B','Racemic epinephrine works quickly but wears off in about 1–2 hours, and symptoms may return. Dexamethasone reduces airway swelling over several hours.','Integrated','Pharmacology'),
('Set32-RN-3','Reduction of Risk Potential','Atrial flutter','single_best_answer','A client''s ECG shows regular "sawtooth" waves between QRS complexes at an atrial rate of about 300/min, with a ventricular rate of 150/min. How should the nurse interpret this rhythm?','Atrial fibrillation|Atrial flutter with 2:1 conduction|Ventricular tachycardia|Sinus tachycardia','B','Atrial flutter produces organized flutter waves. Like atrial fibrillation, it carries stroke risk and may need rate control, anticoagulation, cardioversion, or ablation.','Integrated','Adult Health'),
('Set32-RN-4','Pharmacological and Parenteral Therapies','Mechanical heart valve','single_best_answer','A client with a new mechanical mitral valve asks about anticoagulation. Which response by the nurse is accurate?','"You can take apixaban instead of warfarin."|"You will need warfarin long term, with regular INR checks. A higher target range, often 2.5–3.5, is common for mechanical mitral valves."|"Anticoagulation is only needed for 3 months."|"Aspirin alone is enough."','B','Mechanical valves require lifelong warfarin. Direct oral anticoagulants are contraindicated with mechanical valves because they have been associated with more clots and bleeding.','Integrated','Pharmacology'),
('Set32-RN-5','Health Promotion and Maintenance','Long-term oxygen therapy','single_best_answer','A client with COPD and chronic resting hypoxemia is prescribed home oxygen. Which statement indicates understanding of how to get the most benefit?','"I''ll use it only when I feel short of breath."|"I''ll use my oxygen at least 15 hours a day, including while I sleep."|"I''ll turn it up to 10 liters when I feel tired."|"I''ll stop using it once my breathing feels better."','B','Long-term oxygen used at least 15 hours per day improves survival in COPD with severe resting hypoxemia. The flow rate is used as prescribed.','Integrated','Fundamentals'),
('Set32-RN-6','Pharmacological and Parenteral Therapies','Exercise-induced bronchoconstriction','single_best_answer','A teenager with exercise-induced bronchoconstriction plays soccer. Which instruction should the nurse include?','"Avoid all sports."|"Use your albuterol inhaler about 15 minutes before exercise and warm up gradually."|"Use your inhaled steroid right before games as a rescue."|"Only use albuterol after you finish playing."','B','Pre-exercise short-acting beta agonist use and a gradual warm-up prevent symptoms. Clients should carry their rescue inhaler during activity.','Integrated','Pharmacology'),
('Set32-RN-7','Pharmacological and Parenteral Therapies','Intrathecal baclofen','single_best_answer','A client with severe spasticity has an intrathecal baclofen pump. The pump alarms for a low reservoir, and the client reports itching, increased spasticity, and fever. What should the nurse do?','Wait until the next scheduled refill|Notify the provider immediately, because abrupt baclofen withdrawal can be life-threatening|Give oral acetaminophen and reassess tomorrow|Turn off the pump','B','Intrathecal baclofen withdrawal can progress to high fever, altered mental status, rhabdomyolysis, and death. Prompt pump evaluation and refill are needed.','Integrated','Pharmacology'),
('Set32-RN-8','Reduction of Risk Potential','Delirium screening','single_best_answer','The nurse uses the Confusion Assessment Method (CAM) to screen an older adult for delirium. Which combination of findings is required for a positive screen?','Chronic memory loss only|Acute onset or fluctuating course and inattention, plus either disorganized thinking or an altered level of consciousness|Depressed mood and poor appetite|Hallucinations only','B','The CAM identifies delirium, which requires prompt evaluation for causes such as infection, medications, hypoxia, or electrolyte imbalance.','Integrated','Adult Health'),
('Set32-RN-9','Pharmacological and Parenteral Therapies','Levothyroxine in pregnancy','single_best_answer','A client with hypothyroidism who takes levothyroxine has just learned she is pregnant. What does the nurse anticipate?','Stopping levothyroxine during pregnancy|An increase in the levothyroxine dose, often right away, with TSH checked every few weeks|No change until after delivery|Switching to methimazole','B','Thyroid hormone needs rise early in pregnancy, and adequate levels are important for fetal brain development. Many clients are told to increase the dose as soon as pregnancy is confirmed.','Integrated','Pharmacology'),
('Set32-RN-10','Reduction of Risk Potential','Metformin and B12','single_best_answer','A client who has taken metformin for 8 years reports numbness and tingling in the feet. Which lab test should the nurse anticipate?','Serum amylase|Vitamin B12 level|Thyroid antibodies|Uric acid','B','Long-term metformin use can reduce B12 absorption, which can cause neuropathy that may be mistaken for diabetic neuropathy. Periodic B12 monitoring is recommended.','Integrated','Adult Health'),
('Set32-RN-11','Physiological Adaptation','High-output ileostomy','single_best_answer','A client with a new ileostomy has had 2,400 mL of watery output in 24 hours and reports dizziness and thirst. What is the nurse''s priority concern?','Constipation|Dehydration and electrolyte loss|Hypertension|Stomal prolapse','B','High ileostomy output (often more than about 1.5–2 L/day) can quickly cause dehydration, hyponatremia, hypokalemia, and kidney injury. Oral rehydration solutions, IV fluids, and antimotility drugs may be needed.','Integrated','Adult Health'),
('Set32-RN-12','Basic Care and Comfort','Achalasia','single_best_answer','A client with achalasia reports difficulty swallowing both solids and liquids and regurgitation of undigested food. Which instruction should the nurse include?','"Lie down right after eating."|"Eat small meals slowly, sit upright during and after meals, and raise the head of your bed at night."|"Eat large, dry meals quickly."|"Drink ice-cold drinks with meals."','B','Achalasia is failure of the lower esophageal sphincter to relax. Gravity helps food pass, and head elevation reduces nighttime regurgitation and aspiration risk.','Integrated','Adult Health'),
('Set32-RN-13','Health Promotion and Maintenance','Diabetic kidney disease screening','single_best_answer','Which annual screening test is recommended to detect early kidney disease in adults with diabetes?','Urine albumin-to-creatinine ratio and eGFR|Kidney ultrasound|24-hour urine for cortisol|Urine culture','A','Albuminuria is an early marker of diabetic kidney disease. Early detection allows treatment such as ACE inhibitors, ARBs, or SGLT2 inhibitors to slow progression.','Integrated','Fundamentals'),
('Set32-RN-14','Pharmacological and Parenteral Therapies','Raloxifene','single_best_answer','A postmenopausal client is prescribed raloxifene for osteoporosis. Which history should the nurse report before the first dose?','Seasonal allergies|A previous deep vein thrombosis|Hypothyroidism controlled with medication|Mild osteoarthritis','B','Raloxifene increases the risk of venous thromboembolism and is contraindicated with a history of VTE. It may also worsen hot flashes.','Integrated','Pharmacology'),
('Set32-RN-15','Physiological Adaptation','Iron deficiency anemia','single_best_answer','A client reports craving and chewing large amounts of ice. Which condition should the nurse suspect?','Hypercalcemia|Iron deficiency anemia|Hypothyroidism|Diabetes insipidus','B','Pica, especially craving ice (pagophagia), is associated with iron deficiency. The nurse also looks for the cause, such as heavy menstrual bleeding or GI blood loss.','Integrated','Adult Health'),
('Set32-RN-16','Pharmacological and Parenteral Therapies','Dyspnea at end of life','single_best_answer','A client in hospice with advanced lung cancer is very short of breath and anxious. Which intervention is commonly used to relieve dyspnea?','Withholding all opioids|Low-dose opioids (such as morphine) as prescribed, along with positioning, a fan directed at the face, and oxygen if helpful|Encouraging the client to walk|Keeping the room hot and closed','B','Low-dose opioids reduce the sensation of breathlessness without significantly shortening life when titrated appropriately. Cool airflow and upright positioning also help.','Integrated','Pharmacology'),
('Set32-RN-17','Psychosocial Integrity','Paranoia and touch','single_best_answer','A client with paranoid thinking is pacing and suspicious of staff. Which approach by the nurse is most appropriate?','Approach quickly and touch the client''s arm to reassure them|Maintain personal space, speak calmly and clearly, and explain actions before doing them|Whisper to other staff in front of the client|Stand very close to show support','B','Unexpected touch and closeness can be perceived as threatening by a paranoid client. Clear, honest communication and respecting personal space build trust.','Integrated','Mental Health'),
('Set32-RN-18','Health Promotion and Maintenance','Breastfeeding contraindications','single_best_answer','In which situation should the nurse recognize that breastfeeding is generally contraindicated in the United States?','A mother with a cold|A mother with active, untreated tuberculosis until treatment is established (expressed milk may be given)|A mother taking acetaminophen|A mother who had a cesarean birth','B','Active untreated TB requires temporary separation from direct breastfeeding, although expressed milk can usually be given. Other contraindications include classic galactosemia in the infant and certain drug use. HIV guidance now emphasizes shared decision-making for mothers with sustained viral suppression.','Integrated','Fundamentals'),
('Set32-RN-19','Pharmacological and Parenteral Therapies','Sickle cell disease in children','single_best_answer','The parent of a 2-year-old with sickle cell disease asks why the child takes penicillin every day. What is the nurse''s best response?','"It treats pain crises."|"Children with sickle cell disease have a weakened spleen, so daily penicillin (usually until about age 5) helps prevent life-threatening bacterial infections."|"It increases red blood cells."|"It is only needed during fever." Case study (use for RN Questions 20–25). A 26-year-old client, gravida 1 para 0, at 35 weeks'' gestation comes to labor and delivery reporting a severe headache that is not relieved by acetaminophen and "seeing spots." Nurses'' notes, 1400: Reports pain under the right ribs. Face and hands swollen. Patellar reflexes 4+ with 3 beats of ankle clonus. Fetal heart rate baseline 140/min with moderate variability; no contractions. Vital signs: BP 172/114 mm Hg (repeated 15 minutes later: 168/112), HR 96/min, RR 18/min, SpO2 98% on room air. Laboratory results: urine protein-to-creatinine ratio 0.9 (elevated), platelets 108,000/mm³, AST 88 units/L, ALT 94 units/L, creatinine 1.0 mg/dL.','B','Functional asplenia greatly increases the risk of pneumococcal sepsis. Prophylactic penicillin and vaccinations reduce this risk. Any fever still requires urgent evaluation.','Integrated','Pharmacology'),
('Set33-RN-1','Management of Care','Prioritization: step-down unit','single_best_answer','The nurse receives report on four clients. Which client should the nurse assess first?','A client with a tracheostomy who suddenly cannot pass a suction catheter, has high-pitched breath sounds, and SpO2 dropping to 84%|A client with COPD on 2 L/min oxygen with SpO2 91%|A client with pneumonia requesting cough medicine|A client 2 days after lobectomy who reports incisional pain of 5/10','A','Inability to pass a suction catheter with falling SpO2 suggests tracheostomy tube obstruction (such as a mucus plug) or displacement, an airway emergency.','Integrated','Management of Care'),
('Set33-RN-2','Reduction of Risk Potential','Radial artery access','single_best_answer','A client returns from cardiac catheterization through the right radial artery with a compression band in place. Which action is correct?','Keep the client flat for 6 hours with the leg straight|Monitor the hand for color, warmth, capillary refill, and sensation, and deflate the band gradually per protocol|Take blood pressure on the right arm every 15 minutes|Remove the band all at once after 30 minutes','B','Radial access allows early mobility but requires monitoring for hand ischemia, bleeding, and hematoma. Stepwise band deflation per protocol prevents rebleeding. BP and blood draws are avoided on that arm.','Integrated','Adult Health'),
('Set33-RN-3','Pharmacological and Parenteral Therapies','ACE inhibitor cough','single_best_answer','A client taking enalapril reports a persistent, dry, tickling cough that is disrupting sleep. The lungs are clear. What does the nurse anticipate?','Adding a cough suppressant and continuing enalapril indefinitely|The provider may switch to an ARB such as losartan, which is less likely to cause cough|Doubling the enalapril dose|Starting antibiotics','B','ACE inhibitors increase bradykinin, which can cause a dry cough. ARBs do not increase bradykinin to the same extent. Angioedema, although rare, can also occur.','Integrated','Pharmacology'),
('Set33-RN-4','Pharmacological and Parenteral Therapies','Severe asthma exacerbation','single_best_answer','A client with a severe asthma exacerbation has not improved after repeated albuterol-ipratropium nebulizers and systemic corticosteroids. Which additional medication may the nurse anticipate in the emergency department?','IV magnesium sulfate|Oral montelukast only|Inhaled fluticasone as the rescue drug|A sedative to calm breathing','A','IV magnesium relaxes bronchial smooth muscle and is used for severe exacerbations that don''t respond to initial therapy. Sedatives are avoided because they depress breathing.','Integrated','Pharmacology'),
('Set33-RN-5','Reduction of Risk Potential','Lung-protective ventilation','single_best_answer','A client with ARDS is mechanically ventilated. Which tidal volume setting reflects lung-protective ventilation?','About 10–12 mL/kg of actual body weight|About 6 mL/kg of predicted (ideal) body weight, with plateau pressure kept at or below about 30 cm H2O|The highest volume tolerated|About 15 mL/kg','B','Low tidal volumes reduce ventilator-induced lung injury and improve survival in ARDS. Some rise in CO2 may be accepted (permissive hypercapnia).','Integrated','Adult Health'),
('Set33-RN-6','Health Promotion and Maintenance','Dementia vs normal aging','single_best_answer','A family member is concerned about an older adult''s memory. Which finding is more concerning for dementia than normal aging?','Occasionally forgetting a name but remembering it later|Getting lost while driving to a familiar grocery store|Taking longer to learn a new phone|Misplacing glasses once in a while','B','Disorientation in familiar places, difficulty managing daily tasks, and poor judgment suggest cognitive impairment and need evaluation. Mild slowing and occasional forgetfulness are common with aging.','Integrated','Fundamentals'),
('Set33-RN-7','Health Promotion and Maintenance','After gestational diabetes','single_best_answer','A client had gestational diabetes that resolved after delivery. Which follow-up does the nurse recommend?','"No follow-up is needed because it went away."|"Have a glucose test (often a 75-g oral glucose tolerance test) at about 4–12 weeks postpartum, and ongoing screening at least every 3 years because your risk of type 2 diabetes is higher."|"Check your glucose only if you become pregnant again."|"Start insulin now."','B','Gestational diabetes significantly raises lifetime risk of type 2 diabetes. Healthy weight, activity, and breastfeeding lower that risk.','Integrated','Fundamentals'),
('Set33-RN-8','Health Promotion and Maintenance','Barrett''s esophagus','single_best_answer','A client with long-standing GERD is diagnosed with Barrett''s esophagus. Which teaching point is most important?','"This condition is harmless and needs no follow-up."|"You''ll need periodic endoscopy to watch for precancerous changes, and continuing acid-reducing treatment is important."|"You should stop all medications."|"It will go away on its own in a week."','B','Barrett''s esophagus increases the risk of esophageal adenocarcinoma. Surveillance endoscopy allows early detection and treatment.','Integrated','Fundamentals'),
('Set33-RN-9','Pharmacological and Parenteral Therapies','C. difficile treatment','single_best_answer','A client is diagnosed with a first episode of Clostridioides difficile infection. Which prescription does the nurse expect?','IV vancomycin|Oral vancomycin or oral fidaxomicin|Loperamide to stop the diarrhea|Oral ciprofloxacin','B','IV vancomycin does not reach the colon in meaningful amounts, so oral therapy is used. Antidiarrheals are avoided, and unnecessary antibiotics are stopped when possible.','Integrated','Pharmacology'),
('Set33-RN-10','Physiological Adaptation','Pyelonephritis in pregnancy','single_best_answer','A client at 24 weeks'' gestation has fever, flank pain, and costovertebral angle tenderness. Why is prompt treatment important?','It is a minor infection that resolves on its own|Pyelonephritis in pregnancy can lead to sepsis and preterm labor, so it usually requires hospitalization and IV antibiotics|It only affects the mother''s comfort|Treatment should wait until after delivery','B','Urinary stasis in pregnancy increases the risk of upper UTI. Complications include sepsis, respiratory distress, and preterm labor. Screening for bacteria in the urine helps prevent it.','Integrated','Adult Health'),
('Set33-RN-11','Reduction of Risk Potential','Nephrectomy','single_best_answer','A client is recovering from an open nephrectomy through a flank incision. Which complication should the nurse especially work to prevent?','Hypoglycemia|Atelectasis and pneumonia from shallow breathing because of incisional pain near the diaphragm|Constipation only|Hearing loss','B','Flank incisions near the diaphragm make deep breathing painful. Pain control, splinting, incentive spirometry, and ambulation prevent pulmonary complications. The nurse also monitors urine output from the remaining kidney.','Integrated','Adult Health'),
('Set33-RN-12','Health Promotion and Maintenance','Juvenile idiopathic arthritis','single_best_answer','A 6-year-old is diagnosed with juvenile idiopathic arthritis. Which ongoing screening is especially important?','Hearing tests|Regular eye exams by an ophthalmologist to detect uveitis, which often has no symptoms|Annual chest x-rays|Monthly colonoscopy','B','Uveitis can occur silently in JIA and cause vision loss if untreated. Slit-lamp exams are scheduled based on risk.','Integrated','Fundamentals'),
('Set33-RN-13','Physiological Adaptation','Methemoglobinemia','single_best_answer','After a topical benzocaine spray before a procedure, a client appears cyanotic with SpO2 of about 85% that does not improve with oxygen. The blood drawn appears chocolate-brown. What does the nurse suspect, and which treatment is anticipated?','Pulmonary embolism; heparin|Methemoglobinemia; IV methylene blue|Carbon monoxide poisoning; hyperbaric oxygen|Anemia; iron','B','Methemoglobin cannot carry oxygen. Benzocaine, dapsone, and some other drugs can cause it. Methylene blue restores normal hemoglobin but is used cautiously in G6PD deficiency.','Integrated','Adult Health'),
('Set33-RN-14','Pharmacological and Parenteral Therapies','Hand-foot syndrome','single_best_answer','A client taking capecitabine reports red, swollen, tender palms and soles. Which instruction should the nurse include?','"Take hot showers and scrub your feet."|"Avoid heat and friction, keep your hands and feet cool and moisturized, wear loose shoes, and report blistering or pain that limits activity."|"Walk long distances to toughen your feet."|"This means the drug is not working."','B','Hand-foot syndrome is a common effect of some chemotherapy drugs. Protective measures reduce severity, and a dose adjustment may be needed.','Integrated','Pharmacology'),
('Set33-RN-15','Health Promotion and Maintenance','Vaccines in pregnancy','single_best_answer','A client at 33 weeks'' gestation in September asks which vaccines are recommended during pregnancy. Which response by the nurse is accurate?','"No vaccines are safe during pregnancy."|"Tdap and the inactivated flu vaccine are recommended, and a maternal RSV vaccine is recommended between 32 and 36 weeks during RSV season to protect your baby."|"You should get MMR now."|"Only get vaccines after delivery."','B','Maternal Tdap, influenza, and seasonal RSV vaccination protect both the pregnant person and the newborn through antibody transfer. Live vaccines such as MMR are avoided in pregnancy. COVID-19 vaccination is also recommended.','Integrated','Fundamentals'),
('Set33-RN-16','Pharmacological and Parenteral Therapies','Zolpidem','single_best_answer','A client prescribed zolpidem for insomnia reports waking to find the kitchen messy with no memory of cooking. What should the nurse do?','Reassure the client that this is harmless|Report it, because complex sleep behaviors such as sleep-driving and sleep-cooking are a boxed warning for zolpidem, and the drug should be stopped|Suggest taking it with alcohol to sleep more deeply|Double the dose','B','Complex sleep behaviors can cause serious injury. Zolpidem should be taken only when the client can get a full night''s sleep and should never be combined with alcohol or other CNS depressants.','Integrated','Pharmacology'),
('Set33-RN-17','Psychosocial Integrity','Therapeutic communication: focusing','single_best_answer','A client jumps from topic to topic while describing several stressors. Which response by the nurse demonstrates the technique of focusing?','"Let''s talk about something else."|"You mentioned your job loss several times. Let''s talk more about that."|"Everything will work out."|"Why are you so stressed?"','B','Focusing helps the client concentrate on a key concern and explore it in more depth.','Integrated','Mental Health'),
('Set33-RN-18','Health Promotion and Maintenance','Placental separation','single_best_answer','After delivery of the newborn, which findings indicate the placenta is separating?','The uterus becomes soft and flat|A gush of blood, lengthening of the umbilical cord, and the uterus rising and becoming more globular|Maternal bradycardia|Absence of bleeding for 2 hours','B','These signs usually appear within minutes to 30 minutes after birth. The placenta is examined for completeness, because retained fragments cause hemorrhage.','Integrated','Fundamentals'),
('Set33-RN-19','Pharmacological and Parenteral Therapies','Pediatric epinephrine auto-injector','single_best_answer','A 5-year-old weighing 20 kg is diagnosed with a severe peanut allergy. Which epinephrine auto-injector dose does the nurse expect to be prescribed?','0.3 mg|0.15 mg|1 mg|0.5 mg Case study (use for RN Questions 20–25). A 58-year-old client experiencing homelessness is brought to the emergency department after being found outdoors in freezing weather, wearing wet clothing. Bystanders report the client had been drinking alcohol. Nurses'' notes, 0600: Lethargic and confused; responds to loud voice. Not shivering. Skin cold and pale. Fingers of both hands are white, waxy, hard, and numb. Pupils sluggish. Vital signs: core (esophageal) temperature 86°F (30°C), HR 42/min and irregular, BP 84/50 mm Hg, RR 8/min; pulse oximetry unable to obtain a reliable reading. ECG: slow atrial fibrillation with prominent J (Osborn) waves. Laboratory results: glucose 62 mg/dL, potassium 4.4 mEq/L, blood alcohol elevated.','B','The 0.15-mg auto-injector is generally used for children about 15–30 kg, and 0.3 mg for those 30 kg or more. A 0.1-mg device exists for infants and toddlers weighing about 7.5–15 kg.','Integrated','Pharmacology'),
('Set34-RN-1','Management of Care','Prioritization: school nursing','single_best_answer','A school nurse (RN) has four students waiting. Which student should the nurse see first?','A student with a known peanut allergy who says, "My throat feels itchy and tight," after eating lunch|A student with a scraped knee|A student with type 1 diabetes due for a scheduled glucose check before lunch|A student who reports a mild headache','A','Throat tightness after possible allergen exposure may be the beginning of anaphylaxis. Epinephrine should be given without delay according to the student''s emergency plan.','Integrated','Management of Care'),
('Set34-RN-2','Reduction of Risk Potential','Holter monitor','single_best_answer','A client is going home with a 48-hour Holter monitor. Which instruction should the nurse include?','"Stay in bed while wearing the monitor."|"Continue your normal activities, keep a diary of symptoms and activities with times, and don''t shower or get the monitor wet unless told otherwise."|"Remove the electrodes at night."|"Only record symptoms if they are severe."','B','The Holter records continuous ECG data during usual activities. The symptom diary allows providers to match symptoms with rhythm changes.','Integrated','Adult Health'),
('Set34-RN-3','Pharmacological and Parenteral Therapies','Warfarin before surgery','single_best_answer','A client taking warfarin for atrial fibrillation is scheduled for elective hip replacement. What does the nurse anticipate?','Continuing warfarin up to the morning of surgery|Stopping warfarin about 5 days before surgery, with bridging anticoagulation only if the provider determines high thrombotic risk, and an INR check before surgery|Doubling warfarin the week before|Stopping warfarin permanently','B','Warfarin''s effect lasts several days. Bridging with heparin is reserved for high-risk clients, such as those with mechanical valves or recent stroke, because it increases bleeding.','Integrated','Pharmacology'),
('Set34-RN-4','Health Promotion and Maintenance','After pneumothorax','single_best_answer','A client recovering from a spontaneous pneumothorax asks about travel and hobbies. Which instruction should the nurse include?','"You can fly and go scuba diving right away."|"Avoid air travel until your provider confirms resolution, often a few weeks, and avoid scuba diving unless cleared by a specialist. Stop smoking to reduce recurrence."|"Smoking has no effect on recurrence."|"Recurrence is impossible."','B','Pressure changes during flight and diving can expand residual air or cause recurrence. Smoking greatly increases recurrence risk.','Integrated','Fundamentals'),
('Set34-RN-5','Physiological Adaptation','Pertussis in infants','single_best_answer','A 6-week-old is brought in with a cough for a week. Which finding is most concerning for pertussis in this infant?','Clear nasal discharge only|Episodes of apnea and cyanosis after coughing fits, sometimes without a "whoop"|Occasional sneezing|Mild fussiness after feeding','B','Young infants with pertussis may not whoop but can have life-threatening apnea. They are hospitalized for monitoring, placed on droplet precautions, and treated with a macrolide antibiotic.','Integrated','Adult Health'),
('Set34-RN-6','Reduction of Risk Potential','Restless legs syndrome','single_best_answer','A client reports an irresistible urge to move the legs in the evening that improves with walking. Which lab test does the nurse anticipate?','Serum ferritin (iron studies)|Hemoglobin A1C|Serum amylase|Thyroid antibodies only','A','Iron deficiency is associated with restless legs syndrome, and iron replacement may improve symptoms when ferritin is low. Caffeine, alcohol, and some antidepressants and antihistamines can worsen it.','Integrated','Adult Health'),
('Set34-RN-7','Reduction of Risk Potential','EEG preparation','single_best_answer','A client is scheduled for an EEG. Which instruction should the nurse include?','"Apply hair conditioner the morning of the test."|"Wash your hair the night before without conditioner or styling products, avoid caffeine as instructed, and follow any sleep deprivation instructions."|"Fast for 24 hours."|"Take an extra dose of your sedative."','B','Hair products interfere with electrode contact, and caffeine can affect results. Sleep deprivation may be ordered to increase the chance of capturing abnormal activity. The test is painless.','Integrated','Adult Health'),
('Set34-RN-8','Reduction of Risk Potential','Insulin pump site care','single_best_answer','A client with an insulin pump has unexplained high glucose readings. The infusion site is red and was placed 5 days ago. What should the nurse advise?','"Keep the same site to avoid wasting supplies."|"Change the infusion set and site now, usually every 2–3 days, rotate sites, and check glucose and ketones closely."|"Stop checking glucose."|"Increase carbohydrate intake."','B','Old or infected sites absorb insulin poorly and can cause hyperglycemia and DKA. Regular site changes and rotation prevent problems.','Integrated','Adult Health'),
('Set34-RN-9','Reduction of Risk Potential','H. pylori breath test','single_best_answer','A client is scheduled for a urea breath test for Helicobacter pylori. Which instruction should the nurse include?','"Take your omeprazole the morning of the test."|"Stop proton pump inhibitors about 2 weeks before and antibiotics about 4 weeks before the test, unless your provider instructs otherwise."|"Eat a large meal right before the test."|"No preparation is needed."','B','PPIs, bismuth, and antibiotics suppress H. pylori and can cause false-negative results. Fasting before the test is also typical.','Integrated','Adult Health'),
('Set34-RN-10','Physiological Adaptation','Acute cholangitis','single_best_answer','A client with gallstones develops fever with chills, jaundice, and right upper quadrant pain. What does the nurse suspect?','Uncomplicated biliary colic|Acute cholangitis, which can rapidly progress to sepsis|Hepatitis A|Gastroenteritis','B','Charcot''s triad (fever, jaundice, RUQ pain) suggests infection of the bile ducts from obstruction. Treatment includes antibiotics, fluids, and urgent biliary drainage, often by ERCP. Confusion and hypotension indicate severe disease.','Integrated','Adult Health'),
('Set34-RN-11','Pharmacological and Parenteral Therapies','Urinary retention with BPH','single_best_answer','An older man with benign prostatic hyperplasia took an over-the-counter cold medicine containing pseudoephedrine and diphenhydramine. He now cannot urinate and has lower abdominal pain. What is the likely cause?','Dehydration|Acute urinary retention caused by the decongestant and antihistamine|Kidney stones|Normal aging','B','Decongestants tighten bladder neck muscles, and anticholinergics weaken bladder contraction, causing retention in men with BPH. Catheterization is needed, and clients are taught to avoid these products.','Integrated','Pharmacology'),
('Set34-RN-12','Reduction of Risk Potential','Hot, swollen joint','single_best_answer','A client with a history of gout has a hot, swollen knee and a temperature of 101.8°F (38.8°C). Which test is most important to distinguish gout from a septic joint?','Serum uric acid alone|Joint aspiration with fluid analysis, Gram stain, and culture|X-ray only|Urinalysis','B','Serum uric acid can be normal during a gout flare. Septic arthritis destroys the joint rapidly and requires prompt drainage and antibiotics, and gout and infection can occur together.','Integrated','Adult Health'),
('Set34-RN-13','Pharmacological and Parenteral Therapies','Transfusion rate','single_best_answer','The nurse starts a unit of packed red blood cells for a stable adult. Which approach to the infusion rate is correct?','Infuse at the maximum rate from the beginning|Infuse slowly for the first 15 minutes (often about 2 mL/min) while observing closely, then increase to complete within 4 hours if there is no reaction|Infuse over 6 hours|Pause every 5 minutes','B','Severe reactions such as hemolysis and anaphylaxis usually occur early. A slow start limits the volume given if a reaction occurs. Clients at risk for fluid overload may need slower rates.','Integrated','Pharmacology'),
('Set34-RN-14','Reduction of Risk Potential','Anthracycline cardiotoxicity','single_best_answer','A client who received doxorubicin for breast cancer 2 years ago reports new shortness of breath with activity and ankle swelling. What should the nurse recognize?','These symptoms are unrelated to past treatment|Anthracyclines can cause cardiomyopathy and heart failure, so an echocardiogram evaluation is needed|This is normal aging|The symptoms mean the cancer has returned','B','Doxorubicin cardiotoxicity is dose-related and can appear years later. Cardiac monitoring is part of cancer survivorship care.','Integrated','Adult Health'),
('Set34-RN-15','Pharmacological and Parenteral Therapies','Lyme disease treatment','single_best_answer','A client has an expanding bull''s-eye rash 10 days after a tick bite. Which treatment does the nurse anticipate?','No treatment is needed|Oral doxycycline for early Lyme disease|IV vancomycin|A topical steroid only','B','Erythema migrans is diagnosed clinically and treated with oral antibiotics such as doxycycline. The nurse teaches sun protection and taking doxycycline with water while remaining upright.','Integrated','Pharmacology'),
('Set34-RN-16','Physiological Adaptation','Methamphetamine use','single_best_answer','A client with methamphetamine use disorder is admitted. Which findings are commonly associated with chronic methamphetamine use?','Pinpoint pupils and bradycardia|Severe dental decay, weight loss, skin sores from picking, paranoia, and hypertension|Weight gain and hypothermia|Constricted pupils and respiratory depression','B','Methamphetamine is a potent stimulant. Acute toxicity can cause hyperthermia, dysrhythmias, stroke, and psychosis. Care includes safety, cooling, benzodiazepines for agitation, and referral for treatment.','Integrated','Adult Health'),
('Set34-RN-17','Pharmacological and Parenteral Therapies','Panic disorder treatment','single_best_answer','A client is diagnosed with panic disorder. Which long-term treatment approach does the nurse expect?','Daily benzodiazepines indefinitely as the only treatment|An SSRI or SNRI with cognitive behavioral therapy, and short-term benzodiazepine use only if needed|Avoiding all treatment|Antipsychotics as first-line','B','SSRIs and SNRIs plus CBT are first-line for panic disorder. Long-term benzodiazepine use carries a risk of dependence, falls, and cognitive effects.','Integrated','Pharmacology'),
('Set34-RN-18','Health Promotion and Maintenance','Cervical cerclage','single_best_answer','A client with cervical insufficiency had a cerclage placed at 14 weeks. Which instruction should the nurse include?','"The stitch stays in during vaginal birth."|"Report contractions, leaking fluid, bleeding, or fever right away. The stitch is usually removed around 36–37 weeks."|"You can''t feel anything if the stitch fails."|"Use tampons for any spotting."','B','Labor with a cerclage in place can cause cervical tearing. Signs of labor, rupture of membranes, or infection require prompt evaluation.','Integrated','Fundamentals'),
('Set34-RN-19','Physiological Adaptation','Infant botulism','single_best_answer','A 4-month-old has constipation for several days, a weak cry, poor feeding, and decreased muscle tone. The parent says they sweetened the pacifier with honey. What does the nurse suspect?','Teething|Infant botulism|Colic|Gastroesophageal reflux Case study (use for RN Questions 20–25). A 76-year-old client with atrial fibrillation who is not on anticoagulation (stopped because of falls) arrives at the emergency department with sudden, severe abdominal pain around the umbilicus that began 4 hours ago. The client has vomited twice and had an urgent, forceful bowel movement. Nurses'' notes, 1500: Pain rated 10/10; client is writhing. Abdomen soft, mildly distended, with only mild tenderness and no guarding or rebound. Bowel sounds hyperactive. Vital signs: HR 124/min and irregularly irregular, BP 102/64 mm Hg, RR 24/min, T 99.6°F (37.6°C), SpO2 96% on room air. Laboratory results: lactate 4.8 mmol/L (0.5–2.0), WBC 18,200/mm³, arterial pH 7.29, HCO3 17 mEq/L. CT angiography shows an embolus occluding the superior mesenteric artery.','B','Clostridium botulinum spores in honey can colonize an infant''s immature gut and produce toxin, causing descending weakness. Honey is avoided before age 1. The nurse monitors breathing and swallowing.','Integrated','Adult Health'),
('Set35-RN-1','Management of Care','Prioritization: psychiatric emergency','single_best_answer','The nurse in a psychiatric emergency department is caring for four clients. Which client should the nurse assess first?','A calm client who says they swallowed "a handful of pills" from a friend about an hour ago|A client with schizophrenia who reports hearing voices that are not giving commands|A client with anxiety pacing in the waiting area|A client with depression requesting a sandwich','A','An unknown ingestion within the past hour may be life-threatening even if the client appears calm. Some drugs, such as acetaminophen and extended-release medications, show delayed toxicity. Immediate medical evaluation is needed.','Integrated','Management of Care'),
('Set35-RN-2','Pharmacological and Parenteral Therapies','Antihypertensives in pregnancy','single_best_answer','A client with chronic hypertension who takes lisinopril tells the nurse she is 6 weeks pregnant. What does the nurse anticipate?','Continuing lisinopril|Stopping lisinopril and switching to a pregnancy-compatible antihypertensive such as labetalol or nifedipine|Stopping all BP medications|Adding an ARB','B','ACE inhibitors and ARBs are contraindicated in pregnancy because they can cause fetal kidney damage and other harm. Labetalol, nifedipine, and methyldopa are commonly used instead.','Integrated','Pharmacology'),
('Set35-RN-3','Physiological Adaptation','Reversible causes of cardiac arrest','single_best_answer','During a code for pulseless electrical activity, the team reviews the H''s and T''s. Which condition is one of the reversible causes the team should consider?','Hypothermia|Hypercalcemia only|Hyperthyroidism|Hypertension','A','The H''s are hypovolemia, hypoxia, hydrogen ion (acidosis), hypo- or hyperkalemia, and hypothermia. The T''s are tension pneumothorax, tamponade, toxins, and thrombosis (pulmonary or coronary). Treating the cause can restore circulation.','Integrated','Adult Health'),
('Set35-RN-4','Physiological Adaptation','IVC filter','single_best_answer','A client with a new proximal DVT had a hemorrhagic stroke last week. Which intervention does the nurse anticipate?','Full-dose heparin infusion|Placement of an inferior vena cava (IVC) filter|Thrombolytic therapy|Massage of the leg','B','An IVC filter traps clots and helps prevent pulmonary embolism when anticoagulation is contraindicated, such as after a recent intracranial hemorrhage. Anticoagulation is started when safe.','Integrated','Adult Health'),
('Set35-RN-5','Reduction of Risk Potential','Opioids with obstructive sleep apnea','single_best_answer','A client with obstructive sleep apnea is receiving IV opioids after surgery. Which monitoring does the nurse anticipate?','Vital signs once per shift|Continuous pulse oximetry and, when available, capnography, with the client''s home CPAP used while sleeping|No additional monitoring|Keeping the client flat on the back','B','Clients with OSA are at high risk for opioid-induced respiratory depression. Continuous monitoring, CPAP, head elevation or side-lying positioning, and opioid-sparing analgesia reduce risk.','Integrated','Adult Health'),
('Set35-RN-6','Pharmacological and Parenteral Therapies','Gabapentin','single_best_answer','A client is started on gabapentin for neuropathic pain. Which instruction should the nurse include?','"It works immediately like an opioid."|"It may cause dizziness and drowsiness, so be careful when standing or driving, and don''t stop it suddenly."|"Take it with alcohol for better effect."|"It cures nerve damage."','B','Gabapentin commonly causes sedation and dizziness, increasing fall risk. Abrupt discontinuation can cause withdrawal or seizures. Combining it with opioids increases the risk of respiratory depression.','Integrated','Pharmacology'),
('Set35-RN-7','Pharmacological and Parenteral Therapies','Parkinson''s medication timing','single_best_answer','A hospitalized client with Parkinson''s disease takes carbidopa-levodopa at 0600, 1000, 1400, and 1800. Why is on-time administration important?','Timing doesn''t matter|Late doses can cause sudden worsening of rigidity, tremor, swallowing problems, and fall risk as medication levels drop|Late doses cause hypoglycemia|It only affects sleep','B','Parkinson''s medications are time-critical. Missed or delayed doses can cause "off" periods and serious complications such as aspiration. Hospitals often schedule these doses at the client''s home times.','Integrated','Pharmacology'),
('Set35-RN-8','Health Promotion and Maintenance','A1C goals','single_best_answer','A frail 86-year-old with diabetes, dementia, and a history of falls has an A1C of 7.8%. How should the nurse interpret this in light of current guidelines?','It must be lowered below 6% immediately|A less strict goal (often below 8%) may be appropriate for older adults with frailty or hypoglycemia risk|Diabetes no longer needs any management|The goal for all adults is below 5%','B','A1C goals are individualized. Tight control increases hypoglycemia risk in frail older adults, which can cause falls and cognitive decline. Many healthy adults target below 7%.','Integrated','Fundamentals'),
('Set35-RN-9','Health Promotion and Maintenance','Metabolic syndrome','single_best_answer','Which group of findings is consistent with metabolic syndrome?','Low BP, low triglycerides, and high HDL|Increased waist circumference, elevated triglycerides, low HDL, elevated BP, and elevated fasting glucose|Weight loss and hypoglycemia|Low cholesterol only','B','Metabolic syndrome is diagnosed when three or more of these five criteria are present. It increases the risk of cardiovascular disease and type 2 diabetes, and lifestyle change is the cornerstone of treatment.','Integrated','Fundamentals'),
('Set35-RN-10','Basic Care and Comfort','Ascites management','single_best_answer','A client with cirrhosis and ascites is being discharged. Which instruction should the nurse include?','"Follow a high-sodium diet."|"Limit sodium (often to about 2 g/day), weigh yourself daily, take your diuretics as prescribed, and avoid alcohol and NSAIDs."|"Drink as much fluid as possible."|"Stop your diuretics if you lose weight."','B','Sodium restriction and diuretics (often spironolactone with furosemide) control ascites. Daily weights track fluid, and NSAIDs can cause kidney injury in cirrhosis.','Integrated','Adult Health'),
('Set35-RN-11','Health Promotion and Maintenance','After cholecystectomy','single_best_answer','A client who had a laparoscopic cholecystectomy asks about diet. Which response by the nurse is best?','"You must avoid all fat forever."|"You can usually return to a normal diet, starting with lower-fat meals and adding fat gradually as tolerated. Some people have loose stools at first."|"Eat only liquids for a month."|"Eat very high-fat meals to help digestion."','B','Bile flows continuously into the intestine after gallbladder removal. Most people tolerate a normal diet, although large fatty meals may cause diarrhea initially.','Integrated','Fundamentals'),
('Set35-RN-12','Pharmacological and Parenteral Therapies','Thiazide diuretics','single_best_answer','A client started hydrochlorothiazide for hypertension. Which lab changes should the nurse monitor for?','Hyperkalemia and hypocalcemia|Hypokalemia, hyponatremia, hypercalcemia, hyperglycemia, and hyperuricemia|Hypoglycemia only|No lab changes occur','B','Thiazides cause potassium and sodium loss and calcium retention, and they can raise glucose and uric acid. Gout flares may occur, and older adults are at risk for hyponatremia.','Integrated','Pharmacology'),
('Set35-RN-13','Reduction of Risk Potential','Bone scan','single_best_answer','A client is scheduled for a nuclear medicine bone scan. Which instruction should the nurse include?','"You will need to be isolated for a week."|"After the tracer injection, drink extra fluids and urinate often to help clear the tracer. Remove metal objects before the scan."|"Avoid all fluids before the scan."|"The scan requires general anesthesia."','B','The small tracer dose is cleared mainly through the kidneys. Frequent voiding reduces bladder exposure and improves image quality. There is a waiting period of a few hours between injection and scanning.','Integrated','Adult Health'),
('Set35-RN-14','Pharmacological and Parenteral Therapies','Iron chelation','single_best_answer','A client with beta-thalassemia major receives regular transfusions and has a very high ferritin level. Which treatment does the nurse anticipate?','Oral iron supplements|Iron chelation therapy, such as deferasirox or deferoxamine|Vitamin C megadoses|Stopping all transfusions','B','Repeated transfusions cause iron overload that can damage the heart, liver, and endocrine organs. Chelators bind excess iron for removal. Iron supplements are avoided.','Integrated','Pharmacology'),
('Set35-RN-15','Pharmacological and Parenteral Therapies','Transmucosal fentanyl','single_best_answer','A client with cancer is prescribed a transmucosal fentanyl product for breakthrough pain. Which information is most important for the nurse to verify?','That the client has never taken opioids|That the client is opioid-tolerant (already taking around-the-clock opioids), because these products can cause fatal respiratory depression in opioid-naive people|That the client takes it with grapefruit juice|That the client can chew and swallow it','B','Transmucosal immediate-release fentanyl is restricted to opioid-tolerant clients. Safe storage away from children is essential, because accidental exposure can be fatal.','Integrated','Pharmacology'),
('Set35-RN-16','Safety and Infection Control','Hepatitis C exposure','single_best_answer','A nurse sustains a needlestick from a client with hepatitis','After immediate wound care and reporting, what follow-up does the nurse expect?|No follow-up is needed|Baseline testing, with follow-up HCV RNA and antibody testing over the following weeks to months, and treatment if infection develops|Immediate hepatitis C vaccine|Hepatitis C immune globulin','B','There is no vaccine or post-exposure prophylaxis for hepatitis C. Early detection allows treatment with direct-acting antivirals, which are highly curative.','Integrated','Safety & Infection Control'),
('Set35-RN-17','Psychosocial Integrity','Seasonal affective disorder','single_best_answer','A client reports depressed mood, fatigue, oversleeping, and carbohydrate cravings every winter that resolve in spring. Which treatment should the nurse expect to be discussed?','Staying indoors in a dark room|Bright light therapy, typically in the morning, along with other treatments such as psychotherapy or antidepressants|Using a tanning bed daily|Avoiding all exercise','B','Morning light therapy with a specialized light box helps regulate circadian rhythms. Tanning beds emit UV radiation and are not a substitute.','Integrated','Mental Health'),
('Set35-RN-18','Reduction of Risk Potential','Neonatal phototherapy','single_best_answer','A newborn is receiving phototherapy for hyperbilirubinemia. Which nursing action is correct?','Keep the infant fully clothed under the lights|Place eye protection on the infant, expose as much skin as possible, reposition regularly, monitor temperature and hydration, and continue frequent feedings|Apply lotion to the skin before phototherapy|Stop feedings during treatment','B','Maximal skin exposure increases effectiveness, and eye shields protect the retina. Phototherapy increases fluid loss, so feeding and hydration are maintained. Lotions can cause burns under the lights.','Integrated','Adult Health'),
('Set35-RN-19','Health Promotion and Maintenance','Newborn hepatitis B vaccine','single_best_answer','A parent asks why the newborn needs a hepatitis B vaccine before discharge when the mother tested negative. What is the nurse''s best response?','"It isn''t recommended if the mother tested negative."|"The birth dose is recommended for all medically stable newborns. It protects against infection from unknown exposures and starts the vaccine series early."|"It prevents jaundice."|"It''s only for babies born by cesarean." Case study (use for RN Questions 20–25). A 28-year-old client at 30 weeks'' gestation is brought to labor and delivery after a car crash. She was wearing only the lap belt, positioned across the top of her abdomen. A previous ultrasound showed a fundal (upper uterine) placenta. Nurses'' notes, 1600: Reports severe, constant abdominal pain. Moderate dark red vaginal bleeding. Uterus rigid, tender, and does not relax between frequent small contractions. Fetal heart rate baseline 170/min with minimal variability and recurrent late decelerations. Vital signs: HR 120/min, BP 96/58 mm Hg (prenatal baseline 118/74), RR 24/min, SpO2 97% on room air. Laboratory results: hemoglobin 9.2 g/dL, platelets 110,000/mm³, fibrinogen 150 mg/dL (normal in pregnancy about 300–600), blood type O negative.','B','The universal birth dose, given within 24 hours, is a safety net against missed or unrecognized exposures. Infants infected early have a high risk of chronic infection.','Integrated','Fundamentals'),
('Set36-RN-1','Management of Care','Prioritization: NICU','single_best_answer','The nurse in the neonatal intensive care unit is caring for four infants. Which infant should the nurse assess first?','A 30-week preterm infant with repeated apnea spells longer than 20 seconds and heart rate drops to 70/min|A 34-week infant tolerating gavage feedings|A term infant receiving phototherapy for mild jaundice|A 36-week infant in an open crib with stable temperature','A','Apnea longer than 20 seconds with bradycardia is a life-threatening event requiring immediate stimulation and respiratory support. Caffeine citrate is commonly used for apnea of prematurity.','Integrated','Management of Care'),
('Set36-RN-2','Reduction of Risk Potential','Coarctation of the aorta','single_best_answer','A 22-year-old with hypertension is being evaluated for coarctation of the aorta. Which finding supports this diagnosis?','BP higher in the legs than the arms|BP higher in the arms than the legs, with weak or delayed femoral pulses|Equal pulses in all extremities|Bradycardia with a narrow pulse pressure','B','Narrowing of the aorta, usually beyond the left subclavian artery, causes high pressure proximal to it and reduced flow below it. Normally, leg pressures are equal to or slightly higher than arm pressures.','Integrated','Adult Health'),
('Set36-RN-3','Health Promotion and Maintenance','Thromboangiitis obliterans','single_best_answer','A 35-year-old who smokes is diagnosed with thromboangiitis obliterans (Buerger''s disease) with painful fingertip ulcers. Which intervention is most important?','Increase smoking to reduce stress|Complete cessation of all tobacco and nicotine products|Apply ice to the fingers|Begin high-intensity exercise immediately','B','Buerger''s disease is strongly linked to tobacco use. Complete abstinence is the only intervention proven to halt progression and prevent amputation.','Integrated','Fundamentals'),
('Set36-RN-4','Reduction of Risk Potential','Chest tube tidaling','single_best_answer','The nurse notes that fluctuation (tidaling) in the water-seal chamber of a client''s chest tube has stopped. What should the nurse do?','Clamp the tube|Assess whether the lung has re-expanded or the tubing is kinked, clotted, or obstructed, and check breath sounds and the client''s respiratory status|Strip the tubing vigorously|Increase the suction to maximum','B','Loss of tidaling may mean the lung has fully re-expanded (a chest x-ray confirms) or that the tube is blocked. Dependent loops, kinks, and clots are checked, and new respiratory distress is reported.','Integrated','Adult Health'),
('Set36-RN-5','Safety and Infection Control','Discontinuing TB isolation','single_best_answer','A client with pulmonary tuberculosis has been on treatment for 2 weeks. When can airborne isolation generally be discontinued in the hospital?','As soon as the cough improves|When the client is improving clinically on effective therapy and has three consecutive negative sputum AFB smears collected per protocol|After 24 hours of antibiotics|Only after 6 months of treatment','B','These criteria indicate the client is unlikely to be infectious. Treatment continues for the full course, often with directly observed therapy.','Integrated','Safety & Infection Control'),
('Set36-RN-6','Reduction of Risk Potential','Craniotomy positioning','single_best_answer','A client had a craniotomy for a tumor in the posterior fossa (infratentorial). Which position does the nurse anticipate after surgery?','High-Fowler''s at 90 degrees|Positioning as prescribed by the surgeon, often flat or with slight elevation, lying to the side and avoiding neck flexion|Prone with the neck flexed|Trendelenburg','B','Infratentorial surgery may require flatter positioning to reduce pressure on the incision and brainstem. Supratentorial procedures typically use head-of-bed elevation of about 30 degrees. Surgeon orders guide positioning.','Integrated','Adult Health'),
('Set36-RN-7','Physiological Adaptation','Mechanical thrombectomy','single_best_answer','A client with a large-vessel ischemic stroke arrives 10 hours after last known well and is outside the window for IV alteplase. Which treatment may still be considered?','No treatment is available after 4.5 hours|Mechanical thrombectomy, for selected clients up to 24 hours after last known well based on imaging|IV heparin bolus|Oral aspirin only, immediately, before imaging','B','Thrombectomy can benefit selected clients with large-vessel occlusion and salvageable brain tissue on imaging well beyond the alteplase window. Rapid transfer to a stroke center is key.','Integrated','Adult Health'),
('Set36-RN-8','Pharmacological and Parenteral Therapies','Polycystic ovary syndrome','single_best_answer','A client with polycystic ovary syndrome (PCOS), insulin resistance, and irregular periods is prescribed metformin. How does the nurse explain its purpose?','"It is a hormone that stops ovulation."|"It improves insulin sensitivity, which may help regulate cycles and lower the risk of type 2 diabetes."|"It causes weight gain to balance hormones."|"It is only for pain."','B','Insulin resistance drives many PCOS features. Lifestyle changes and metformin improve metabolic health, and hormonal contraceptives may also be used to regulate cycles.','Integrated','Pharmacology'),
('Set36-RN-9','Health Promotion and Maintenance','Nutrition after gastric bypass','single_best_answer','A client is going home after Roux-en-Y gastric bypass. Which long-term instruction is most important?','"You won''t need vitamins after surgery."|"Take lifelong supplements as prescribed, including a multivitamin, calcium with vitamin D, vitamin B12, and iron, and have regular lab monitoring."|"Eat large meals to prevent weight loss."|"Drink carbonated drinks with meals."','B','Bypass surgery reduces absorption of several nutrients, leading to deficiencies such as anemia, bone loss, and neuropathy if not supplemented.','Integrated','Fundamentals'),
('Set36-RN-10','Basic Care and Comfort','Post-hemorrhoidectomy care','single_best_answer','A client had a hemorrhoidectomy this morning. Which instruction should the nurse include?','"Avoid having a bowel movement for a week."|"Take the prescribed stool softener and pain medication, use sitz baths, drink fluids, and don''t delay your first bowel movement, although it may be uncomfortable."|"Strain to empty your bowels completely."|"Sit on a hard chair for long periods."','B','Delaying bowel movements leads to hard stool and more pain. Softeners, fluids, analgesia, and warm sitz baths ease recovery. Heavy bleeding or inability to void is reported.','Integrated','Adult Health'),
('Set36-RN-11','Reduction of Risk Potential','Pediatric urine output','single_best_answer','A 20-kg child is recovering from surgery. What is the minimum acceptable urine output per hour?','About 5 mL/hr|About 20 mL/hr (1 mL/kg/hr)|About 100 mL/hr|About 200 mL/hr','B','Children generally should produce at least about 1 mL/kg/hr, and infants about 1–2 mL/kg/hr. Lower output suggests inadequate perfusion or dehydration.','Integrated','Adult Health'),
('Set36-RN-12','Basic Care and Comfort','Hip spica cast','single_best_answer','A toddler is in a hip spica cast. Which instruction should the nurse give the parents?','"Put the diaper over the cast."|"Tuck a small diaper inside the cast edges at the perineal opening, cover it with a larger diaper, check the skin at the cast edges often, and never lift the child by the abduction bar."|"Let the child stand on the cast right away."|"Stuff small toys inside the cast for comfort."','B','Keeping urine and stool away from the cast prevents soiling and skin breakdown. The bar is not a handle. Small objects placed inside the cast can cause pressure injuries.','Integrated','Adult Health'),
('Set36-RN-13','Physiological Adaptation','Massive transfusion','single_best_answer','A trauma client is receiving a massive transfusion of many units of blood products. Which complications should the nurse monitor for?','Hyperglycemia and hypernatremia|Hypocalcemia from citrate, hypothermia, and coagulopathy|Hypokalemia only|Hypertension and bradycardia only','B','Citrate binds calcium. Cold blood causes hypothermia, which worsens bleeding. Replacing red cells without enough plasma and platelets dilutes clotting factors. Blood warmers, calcium replacement, and balanced ratios are used.','Integrated','Adult Health'),
('Set36-RN-14','Health Promotion and Maintenance','Aromatase inhibitors','single_best_answer','A postmenopausal client is taking anastrozole after treatment for breast cancer. Which monitoring does the nurse expect?','Weekly INR checks|Baseline and periodic bone density testing, since aromatase inhibitors can cause bone loss|Daily blood glucose checks|Monthly chest x-rays','B','Lowering estrogen accelerates bone loss. Calcium, vitamin D, weight-bearing exercise, and sometimes bisphosphonates help. Joint aches are also common.','Integrated','Fundamentals'),
('Set36-RN-15','Health Promotion and Maintenance','Shingles vaccine in immunocompromise','single_best_answer','A 45-year-old receiving immunosuppressive therapy for rheumatoid arthritis asks about the shingles vaccine. Which response is accurate?','"You can''t get any shingles vaccine because you''re immunocompromised."|"The recombinant (non-live) shingles vaccine is recommended for adults 19 and older with weakened immune systems, so ask your provider about timing."|"You need the live shingles vaccine."|"Only people over 80 can get it."','B','The recombinant zoster vaccine is non-live, so it is safe and recommended for immunocompromised adults 19 and older. Timing may be coordinated with immunosuppressive therapy.','Integrated','Fundamentals'),
('Set36-RN-16','Reduction of Risk Potential','Long-term lithium monitoring','single_best_answer','A client has taken lithium for many years. In addition to lithium levels, which labs should the nurse expect to be monitored?','Liver enzymes only|Thyroid function (TSH) and kidney function (creatinine/eGFR), plus calcium|Hemoglobin A1C only|Amylase and lipase','B','Lithium can cause hypothyroidism, chronic kidney disease, nephrogenic diabetes insipidus, and hyperparathyroidism. Regular monitoring detects these problems early.','Integrated','Adult Health'),
('Set36-RN-17','Reduction of Risk Potential','Postterm pregnancy','single_best_answer','A client is at 41 weeks and 3 days of gestation. Which concern guides the nurse''s teaching and the planned monitoring?','Postterm pregnancy has no added risk|Risk of decreasing placental function and amniotic fluid (oligohydramnios), with increased risk of fetal compromise and meconium, so fetal surveillance and discussion of induction are recommended|Risk of the fetus being too small to deliver|Risk of preterm labor','B','After 41 weeks, placental aging increases the risk of stillbirth, macrosomia, and meconium aspiration. Nonstress tests, amniotic fluid assessment, and induction are commonly offered.','Integrated','Adult Health'),
('Set36-RN-18','Reduction of Risk Potential','Amniotomy','single_best_answer','Immediately after the provider performs an amniotomy (artificial rupture of membranes), what should the nurse do first?','Document the time only|Assess the fetal heart rate and note the color, amount, and odor of the amniotic fluid|Encourage the client to walk right away|Administer oxytocin immediately','B','Rupture of membranes can cause cord prolapse, which shows as FHR changes. Green (meconium-stained), bloody, or foul-smelling fluid requires further evaluation.','Integrated','Adult Health'),
('Set36-RN-19','Physiological Adaptation','Infant heart failure','single_best_answer','A 2-month-old with a large ventricular septal defect is being monitored for heart failure. Which findings should the nurse report?','Steady weight gain and feeding in 15 minutes|Sweating and fast breathing during feedings, tiring before finishing bottles, and poor weight gain|Sleeping 16 hours a day|Pink mucous membranes Case study (use for RN Questions 20–25). A 19-year-old client with Burkitt lymphoma began induction chemotherapy 30 hours ago. The client received IV fluids and allopurinol before chemotherapy. Nurses'' notes, 0800: Reports nausea, fatigue, muscle cramps, tingling around the mouth, and a "fluttering" feeling in the chest. Urine output 20 mL/hr for the past 3 hours. Positive Chvostek''s sign. Vital signs: HR 110/min with frequent PVCs, BP 150/90 mm Hg, RR 20/min, SpO2 97% on room air, T 98.8°F (37.1°C). 12-lead ECG: peaked T waves. Laboratory results: potassium 6.6 mEq/L, phosphorus 8.9 mg/dL (2.5–4.5), calcium 6.8 mg/dL (8.6–10.2), uric acid 14.2 mg/dL (3.5–7.2), creatinine 2.3 mg/dL (baseline 0.8), BUN 45 mg/dL. G6PD status: not yet documented.','B','Feeding is exertion for infants. Tachypnea, diaphoresis, and fatigue during feeds with poor growth suggest heart failure. Management includes diuretics and high-calorie feeds, often with surgical repair.','Integrated','Adult Health'),
('Set37-RN-1','Management of Care','Prioritization: obstetric phone triage','single_best_answer','The obstetric triage nurse receives four phone calls. Which client should the nurse call back first?','A client at 38 weeks who reports the baby has moved much less than usual for the past 12 hours|A client at 12 weeks with morning nausea|A client at 28 weeks asking about a glucose test appointment|A client at 34 weeks with mild ankle swelling in the evening','A','Decreased fetal movement can signal fetal compromise and needs prompt evaluation, such as a nonstress test. The other concerns are routine.','Integrated','Management of Care'),
('Set37-RN-2','Health Promotion and Maintenance','Peripheral arterial disease exercise','single_best_answer','A client with peripheral arterial disease has calf pain when walking one block. Which recommendation is most effective for improving walking distance?','"Avoid walking to prevent pain."|"Join a supervised exercise program: walk until moderate pain, rest until it resolves, then repeat, for about 30–45 minutes at least three times a week."|"Elevate your legs above your heart when they hurt."|"Use a heating pad on your legs daily."','B','Structured walking programs promote collateral circulation and significantly increase pain-free walking distance. Smoking cessation and medications are also important.','Integrated','Fundamentals'),
('Set37-RN-3','Health Promotion and Maintenance','Sternal precautions','single_best_answer','A client is going home after coronary artery bypass surgery through a median sternotomy. Which instruction should the nurse include?','"Push yourself up from the bed with both arms."|"Avoid lifting, pushing, or pulling more than about 5–10 lb, and don''t drive until cleared. Hug a pillow when you cough."|"Resume weightlifting next week."|"Reach over your head often to stretch the incision."','B','Sternal precautions protect the healing sternum from separation. Some programs now use individualized "move in the tube" guidance, but heavy strain is still avoided early on.','Integrated','Fundamentals'),
('Set37-RN-4','Reduction of Risk Potential','D-dimer','single_best_answer','A client with a low clinical probability of pulmonary embolism has a normal D-dimer result. How should the nurse interpret this?','PE is confirmed|A normal D-dimer in a low-probability client helps rule out PE|The test must be repeated daily|D-dimer is only used for heart attacks','B','D-dimer is sensitive but not specific. A normal result makes a clot unlikely in low-risk clients. An elevated result is nonspecific and occurs with surgery, pregnancy, infection, and older age.','Integrated','Adult Health'),
('Set37-RN-5','Physiological Adaptation','Open pneumothorax','single_best_answer','A client has a stab wound to the chest with air bubbling and a sucking sound during breathing. What should the nurse do first?','Pack the wound tightly with gauze|Cover the wound with a vented chest seal or a sterile occlusive dressing taped on three sides, and monitor for tension pneumothorax|Leave the wound open|Have the client lie on the uninjured side and walk','B','A vented dressing prevents air from entering during inspiration while allowing trapped air to escape, reducing the risk of tension pneumothorax. Chest tube placement follows.','Integrated','Adult Health'),
('Set37-RN-6','Physiological Adaptation','Chronic subdural hematoma','single_best_answer','An 80-year-old taking apixaban fell 3 weeks ago without apparent injury. The family now reports gradually worsening confusion, headaches, and unsteady walking. What does the nurse suspect?','Normal aging|A chronic subdural hematoma|An acute epidural hematoma|Urinary tract infection only','B','Brain atrophy stretches bridging veins in older adults, and anticoagulation increases the risk of slow bleeding. Symptoms can develop weeks after minor trauma and may be mistaken for dementia. A CT scan is needed.','Integrated','Adult Health'),
('Set37-RN-7','Physiological Adaptation','BP in acute ischemic stroke','single_best_answer','A client with an acute ischemic stroke is not eligible for thrombolytics or thrombectomy. BP is 196/104 mm Hg. What does the nurse anticipate?','Rapidly lowering BP to 120/80 mm Hg|Permissive hypertension, avoiding treatment unless BP exceeds about 220/120 mm Hg in the first 24–48 hours, to preserve blood flow to at-risk brain tissue|Giving IV nitroprusside immediately to normalize BP|Stopping all monitoring','B','Lowering BP too quickly can extend the infarct. Clients receiving alteplase have stricter targets (below 185/110 before and 180/105 after).','Integrated','Adult Health'),
('Set37-RN-8','Health Promotion and Maintenance','Hypoglycemia unawareness','single_best_answer','A client with long-standing type 1 diabetes no longer feels shaky or sweaty before low glucose readings and had a severe low while driving. Which intervention should the nurse anticipate?','Tightening glucose targets further|Strictly avoiding hypoglycemia for several weeks, raising glucose targets temporarily, using a CGM with alerts, and checking glucose before driving|Stopping insulin|Driving only at night','B','Repeated hypoglycemia blunts warning symptoms. Avoiding lows for 2–3 weeks can restore awareness. CGM alarms and checking glucose before driving improve safety.','Integrated','Fundamentals'),
('Set37-RN-9','Health Promotion and Maintenance','Chronic pancreatitis','single_best_answer','A client with chronic pancreatitis has greasy, foul-smelling stools and weight loss. Which instruction is most important?','"Take pancreatic enzymes with every meal and snack, avoid alcohol completely, and have your glucose checked regularly."|"Eat a very high-fat diet."|"Drink alcohol in moderation."|"Take enzymes once a week."','A','Loss of exocrine function causes fat malabsorption, and loss of endocrine function can cause diabetes. Alcohol cessation slows progression, and fat-soluble vitamins may be needed.','Integrated','Fundamentals'),
('Set37-RN-10','Health Promotion and Maintenance','Ulcerative colitis','single_best_answer','A client with long-standing ulcerative colitis in remission on mesalamine asks about follow-up. Which information should the nurse include?','"No follow-up is needed once symptoms go away."|"Continue your maintenance medication, and plan regular surveillance colonoscopies because long-standing UC increases colon cancer risk."|"Stop mesalamine when you feel well."|"Colon cancer risk is lower with UC."','B','Surveillance usually begins about 8 years after diagnosis. Maintenance therapy reduces flares and may lower cancer risk.','Integrated','Fundamentals'),
('Set37-RN-11','Safety and Infection Control','Intravesical BCG','single_best_answer','A client receives intravesical BCG for superficial bladder cancer. Which instruction should the nurse include?','"Urinate immediately after the treatment."|"Hold the solution in your bladder for about 2 hours as instructed. For about 6 hours afterward, sit to urinate, add bleach to the toilet for 15 minutes before flushing, and wash your hands and genitals."|"BCG is not infectious."|"Drink no fluids for 24 hours."','B','BCG is a live, attenuated bacterium. Retention allows contact with the bladder lining. Disinfection protects household members. Fever or flu-like symptoms lasting more than 48 hours should be reported.','Integrated','Safety & Infection Control'),
('Set37-RN-12','Physiological Adaptation','Vertebral compression fracture','single_best_answer','A 72-year-old with osteoporosis reports sudden mid-back pain after lifting a laundry basket. Height has decreased by 1.5 inches since last year. What does the nurse suspect?','A muscle strain only|A vertebral compression fracture|Kidney stones|Normal aging with no fracture','B','Osteoporotic vertebral fractures can occur with minimal stress and cause height loss and kyphosis. Pain management, early mobility, and osteoporosis treatment are important.','Integrated','Adult Health'),
('Set37-RN-13','Physiological Adaptation','Delayed hemolytic transfusion reaction','single_best_answer','Ten days after a transfusion, a client has fever, mild jaundice, and a hemoglobin that has dropped below the post-transfusion level. What does the nurse suspect?','An acute hemolytic reaction|A delayed hemolytic transfusion reaction|Iron deficiency anemia|Hepatitis A','B','Delayed hemolysis occurs 3–14 days later when antibodies to minor red cell antigens develop. It is usually milder than acute hemolysis. The blood bank is notified, and future transfusions need antigen-matched blood.','Integrated','Adult Health'),
('Set37-RN-14','Pharmacological and Parenteral Therapies','Delayed chemotherapy nausea','single_best_answer','A client received highly emetogenic chemotherapy yesterday and is now having nausea at home on day 2. Which teaching is most important?','"Nausea only happens on the day of treatment."|"Take your prescribed antiemetics on schedule for the full number of days, not just when nausea is severe, and call if you can''t keep fluids down."|"Stop eating for 3 days."|"Take antiemetics only once a week."','B','Delayed nausea commonly peaks days 2–3. Scheduled prophylaxis works better than treating established nausea. Dehydration needs prompt intervention.','Integrated','Pharmacology'),
('Set37-RN-15','Physiological Adaptation','Neonatal sepsis','single_best_answer','A 5-day-old newborn is brought in with poor feeding, lethargy, and a temperature of 96.5°F (35.8°C). What does the nurse suspect?','Normal newborn behavior|Possible neonatal sepsis, which often causes temperature instability, including low temperature, rather than fever|Teething|Overdressing','B','Newborns with serious infection may have hypothermia, lethargy, poor feeding, or apnea. Urgent evaluation with cultures and empiric antibiotics is needed.','Integrated','Adult Health'),
('Set37-RN-16','Psychosocial Integrity','Gender-affirming care','single_best_answer','A transgender client''s legal name in the record differs from the name they use. Which action by the nurse is most appropriate?','Use the legal name in all conversations|Ask the client which name and pronouns they use, use them consistently, and document per facility policy while using legal identifiers for safety checks|Avoid addressing the client by name|Ask the client''s family instead','B','Respecting chosen names and pronouns supports dignity and trust. Two-identifier verification still uses legal information to ensure safety.','Integrated','Mental Health'),
('Set37-RN-17','Physiological Adaptation','Uterine inversion','single_best_answer','During delivery of the placenta, the nurse sees a mass protruding from the vagina, and the client has sudden hemorrhage and hypotension. The fundus cannot be felt abdominally. What should the nurse do?','Pull on the umbilical cord to deliver the placenta|Call for emergency help immediately, stop any oxytocin infusion, and prepare for immediate uterine repositioning and resuscitation|Massage the fundus vigorously|Place the client in high-Fowler''s position','B','Uterine inversion is a life-threatening emergency. Oxytocin is stopped until the uterus is repositioned, and then given to keep it contracted. Traction on the cord before separation is a risk factor.','Integrated','Adult Health'),
('Set37-RN-18','Physiological Adaptation','Meconium-stained fluid','single_best_answer','A newborn is born through meconium-stained amniotic fluid and is crying vigorously with good tone. What does the nurse anticipate under current neonatal resuscitation guidelines?','Immediate intubation and tracheal suctioning|Routine newborn care with the mother, including clearing secretions from the mouth and nose as needed|Deep suctioning of the stomach|Transfer to the NICU regardless of condition','B','Vigorous newborns need no special intervention. Routine intubation for suctioning is no longer recommended, even for nonvigorous newborns. The team monitors for respiratory distress.','Integrated','Adult Health'),
('Set37-RN-19','Physiological Adaptation','Infant urinary tract infection','single_best_answer','A 4-month-old has a fever of 102.4°F (39.1°C) without an obvious source. Which test does the nurse anticipate?','Chest x-ray only|Urinalysis and urine culture, collected by catheterization|Throat culture|Stool culture Case study (use for RN Questions 20–25). A 3-year-old is admitted with a fever of 103–104°F (39.4–40°C) for 6 days that has not responded to acetaminophen or ibuprofen. Nurses'' notes, 1000: Very irritable and difficult to console. Both eyes red without drainage. Lips red, dry, and cracked, with a bright red "strawberry" tongue. Blotchy red rash on the trunk. Hands and feet swollen and red. A single enlarged, tender lymph node (2 cm) on the right side of the neck. Lungs clear. Capillary refill 2 seconds. Vital signs: T 103.8°F (39.9°C), HR 156/min, RR 30/min, BP 96/60 mm Hg. Weight 14 kg. Laboratory results: C-reactive protein and ESR markedly elevated, platelets 520,000/mm³, albumin 2.8 g/dL, ALT mildly elevated, urinalysis with sterile pyuria. Echocardiogram is scheduled.','B','UTI is a common cause of fever without a source in infants, who often have nonspecific symptoms. Bag specimens are unreliable for culture. Imaging may follow to evaluate for reflux.','Integrated','Adult Health'),
('Set38-RN-1','Management of Care','Prioritization: hemodialysis unit','single_best_answer','The nurse in an outpatient hemodialysis unit is caring for four clients. Which client should the nurse assess first?','A client 1 hour into treatment who reports new chest pain, with BP falling from 138/80 to 82/50 mm Hg|A client reporting mild leg cramps near the end of treatment|A client asking for a snack|A client whose fistula has a strong thrill and bruit','A','Chest pain with sudden hypotension during dialysis may indicate cardiac ischemia, hemorrhage, air embolism, or a reaction. The nurse stops or slows ultrafiltration, places the client in Trendelenburg or supine position, and escalates. Leg cramps are common and less urgent.','Integrated','Management of Care'),
('Set38-RN-2','Health Promotion and Maintenance','Myocarditis','single_best_answer','A 20-year-old college athlete is recovering from viral myocarditis. Which instruction is most important?','"You can return to competitive sports next week."|"Avoid competitive sports and strenuous exercise for several months, typically 3–6, until cleared by cardiology, because exertion increases the risk of dangerous heart rhythms."|"Exercise will speed healing of the heart muscle."|"Myocarditis never causes lasting effects."','B','Myocarditis is a known cause of sudden cardiac death in young athletes. Return to sport requires evaluation that may include ECG, echocardiogram, and exercise testing.','Integrated','Fundamentals'),
('Set38-RN-3','Pharmacological and Parenteral Therapies','Dual antiplatelet therapy','single_best_answer','A client who had a drug-eluting coronary stent placed 2 months ago tells the nurse they plan to stop clopidogrel before a dental cleaning. What is the nurse''s best response?','"That''s fine; stop it a week before."|"Don''t stop clopidogrel without talking to your cardiologist, because stopping early greatly increases the risk of a clot forming in the stent."|"Stop aspirin instead."|"Double the dose after the cleaning."','B','Premature discontinuation of dual antiplatelet therapy is a major cause of stent thrombosis, which can cause MI or death. Most dental cleanings can be done while continuing antiplatelets.','Integrated','Pharmacology'),
('Set38-RN-4','Physiological Adaptation','Hypercapnia','single_best_answer','A client with COPD is given high-flow oxygen by mistake. The client becomes drowsy and has a headache, and the skin is warm and flushed. What does the nurse suspect?','Hypoglycemia|Rising carbon dioxide levels (hypercapnia)|Anaphylaxis|Hypothermia','B','Hypercapnia causes vasodilation (flushed skin, headache) and CNS depression. The nurse obtains an ABG, adjusts oxygen to the target range, and prepares for ventilatory support if needed.','Integrated','Adult Health'),
('Set38-RN-5','Reduction of Risk Potential','Thoracentesis volume','single_best_answer','During a thoracentesis, 1,500 mL of fluid has been removed. The client develops coughing and chest tightness. What should the nurse anticipate?','Continuing to drain until no more fluid remains|Stopping the procedure, because removing large volumes quickly can cause re-expansion pulmonary edema|Increasing the drainage rate|Having the client lie flat','B','Many providers limit removal to about 1–1.5 L at a time. Coughing, chest discomfort, and dyspnea are signals to stop. The nurse monitors for hypoxemia and hypotension.','Integrated','Adult Health'),
('Set38-RN-6','Pharmacological and Parenteral Therapies','Essential tremor','single_best_answer','A client with essential tremor is prescribed propranolol. Which condition in the client''s history should the nurse report before the first dose?','Seasonal allergies|Asthma with frequent bronchospasm|Mild osteoarthritis|Hypothyroidism controlled with medication','B','Propranolol is a nonselective beta blocker that can trigger bronchospasm. It can also mask hypoglycemia and cause bradycardia and fatigue. Primidone is an alternative.','Integrated','Pharmacology'),
('Set38-RN-7','Reduction of Risk Potential','Lumbar puncture contraindications','single_best_answer','A client with suspected meningitis has papilledema, new confusion, and a focal neurological deficit. What does the nurse anticipate before any lumbar puncture?','Proceeding with the lumbar puncture immediately|A head CT to rule out a mass or raised ICP before the lumbar puncture, with antibiotics given without delay|Delaying antibiotics until after the lumbar puncture|Performing the lumbar puncture with the client sitting upright only','B','Removing CSF when ICP is elevated from a mass lesion can cause brain herniation. Empiric antibiotics are not delayed for imaging.','Integrated','Adult Health'),
('Set38-RN-8','Health Promotion and Maintenance','Diabetes before pregnancy','single_best_answer','A client with type 1 diabetes plans to become pregnant next year. Which recommendation should the nurse emphasize?','"Glucose control doesn''t matter until the third trimester."|"Aim for tight glucose control before conception (often an A1C below 6.5% if safely achievable), take folic acid, and review medications with your provider."|"Stop insulin when you become pregnant."|"Pregnancy will cure your diabetes."','B','High glucose during organ formation in early pregnancy increases the risk of birth defects and miscarriage. Preconception care improves outcomes. Some medications, such as ACE inhibitors and statins, are stopped.','Integrated','Fundamentals'),
('Set38-RN-9','Health Promotion and Maintenance','Esophageal cancer warning signs','single_best_answer','A 66-year-old with long-standing GERD reports that swallowing has become harder over several months, first with solids and now with soft foods, along with a 15-lb weight loss. What should the nurse do?','Recommend drinking more water with meals|Refer promptly for evaluation, because progressive difficulty swallowing with weight loss is a warning sign of esophageal cancer|Suggest eating faster|Reassure the client that this is normal aging','B','Progressive dysphagia from solids to liquids suggests a narrowing, such as a tumor or stricture. Endoscopy is needed.','Integrated','Fundamentals'),
('Set38-RN-10','Reduction of Risk Potential','GI bleeding risk with combined drugs','single_best_answer','An older adult takes daily naproxen for arthritis and was recently started on sertraline. Why is the nurse concerned?','The combination causes hypertension|The combination increases the risk of GI bleeding|The combination causes hyperglycemia|There is no concern','B','NSAIDs damage the gastric lining, and SSRIs impair platelet function. Together they raise bleeding risk. The provider may consider a safer analgesic or a PPI.','Integrated','Adult Health'),
('Set38-RN-11','Basic Care and Comfort','Epididymitis','single_best_answer','A client with acute epididymitis has a painful, swollen scrotum. Which comfort measures should the nurse recommend with the prescribed antibiotics?','Heat applied directly for hours|Scrotal support or elevation, cold packs, rest, and pain relief|Vigorous exercise|Tight-fitting clothing','B','Support and cold reduce swelling and pain. Sexually transmitted causes require partner treatment. Sudden severe pain in younger males must be distinguished from testicular torsion.','Integrated','Adult Health'),
('Set38-RN-12','Pharmacological and Parenteral Therapies','Topical NSAIDs','single_best_answer','An 80-year-old with knee osteoarthritis and chronic kidney disease asks about pain relief. Which option has lower systemic risk than oral NSAIDs?','High-dose oral ibuprofen|Topical diclofenac gel applied to the knee as directed|Oral naproxen twice daily|Aspirin 1,000 mg four times daily','B','Topical NSAIDs provide local relief with much lower blood levels, which reduces GI, kidney, and cardiovascular risks. Acetaminophen is another option.','Integrated','Pharmacology'),
('Set38-RN-13','Pharmacological and Parenteral Therapies','Rivaroxaban','single_best_answer','A client is prescribed rivaroxaban 20 mg daily for atrial fibrillation. Which instruction should the nurse include?','"Take it on an empty stomach."|"Take this dose with your evening meal for proper absorption, and report any unusual bleeding."|"Have weekly INR checks."|"Stop it before dental work without asking."','B','The 15-mg and 20-mg rivaroxaban doses are absorbed better with food. INR monitoring is not used, and doses are not stopped without provider guidance.','Integrated','Pharmacology'),
('Set38-RN-14','Health Promotion and Maintenance','Androgen deprivation therapy','single_best_answer','A client receiving androgen deprivation therapy for prostate cancer asks about side effects. Which should the nurse include?','Increased muscle mass|Hot flashes, decreased libido, bone loss, fatigue, and increased metabolic and cardiovascular risk|Improved bone density|Weight loss','B','Lowering testosterone causes these effects. Bone density monitoring, calcium and vitamin D, exercise, and cardiovascular risk management are recommended.','Integrated','Fundamentals'),
('Set38-RN-15','Pharmacological and Parenteral Therapies','Syphilis treatment','single_best_answer','A client is diagnosed with early (primary) syphilis and has no penicillin allergy. Which treatment does the nurse anticipate?','Oral amoxicillin for 3 days|A single IM injection of benzathine penicillin G|Topical antifungal cream|No treatment','B','Benzathine penicillin G is the treatment of choice. Clients are monitored for a Jarisch-Herxheimer reaction, and partners are notified and treated. Follow-up blood tests confirm the response.','Integrated','Pharmacology'),
('Set38-RN-16','Psychosocial Integrity','Transference','single_best_answer','A client says to the nurse, "You''re just like my mother. You never listen to me," although the nurse has only just met the client. What is this an example of?','Countertransference|Transference|Projection of the nurse''s feelings|Sublimation','B','Transference occurs when a client unconsciously directs feelings from past relationships onto the nurse. Countertransference is the nurse''s emotional reaction to the client. The nurse stays professional and explores the client''s feelings.','Integrated','Mental Health'),
('Set38-RN-17','Pharmacological and Parenteral Therapies','Nitrous oxide in labor','single_best_answer','A laboring client chooses self-administered nitrous oxide for pain relief. Which instruction should the nurse give?','"The nurse will hold the mask tightly on your face continuously."|"Hold the mask yourself and start breathing the gas about 30 seconds before a contraction begins. If you get drowsy, you''ll naturally drop the mask."|"It will completely eliminate all pain."|"You''ll need to stay NPO for a week."','B','Self-administration is a built-in safety feature, because a drowsy client lets go of the mask. Starting before the contraction lets the gas peak with the pain. It reduces but does not eliminate pain.','Integrated','Pharmacology'),
('Set38-RN-18','Physiological Adaptation','Transient tachypnea of the newborn','single_best_answer','A term newborn born by scheduled cesarean has a respiratory rate of 80/min with mild grunting at 2 hours of age. SpO2 is 94%, and the chest x-ray shows fluid in the fissures. What does the nurse suspect?','Meconium aspiration|Transient tachypnea of the newborn|Respiratory distress syndrome of prematurity|Congenital heart disease only','B','Delayed clearance of fetal lung fluid, which is more common after cesarean birth without labor, causes TTN. It usually resolves in 24–72 hours with supportive care. The infant is monitored for worsening distress.','Integrated','Adult Health'),
('Set38-RN-19','Health Promotion and Maintenance','Retinoblastoma','single_best_answer','A parent notices that in flash photos, one of the 18-month-old''s pupils looks white instead of red. What should the nurse advise?','"It''s just the camera angle."|"Schedule a prompt eye exam, because a white pupillary reflex can be a sign of retinoblastoma, a childhood eye cancer."|"Check again when your child is 5."|"Use eye drops." Case study (use for RN Questions 20–25). A 34-year-old client with epilepsy ran out of levetiracetam 4 days ago. The client is brought to the emergency department by EMS after a generalized tonic-clonic seizure that began at home. Nurses'' notes, 2210: The client has had continuous generalized tonic-clonic activity for 7 minutes (including prehospital time) without regaining consciousness between convulsions. Gurgling respirations with frothy, blood-tinged oral secretions from a bitten tongue. Urinary incontinence. No IV access yet. Vital signs: HR 136/min, BP 172/100 mm Hg, RR 28/min and irregular, SpO2 86% on room air, T 101.0°F (38.3°C). Point-of-care results: glucose 58 mg/dL, sodium 136 mEq/L.','B','Leukocoria is the most common presenting sign of retinoblastoma. Early detection preserves vision and life. Strabismus can be another sign.','Integrated','Fundamentals'),
('Set39-RN-1','Management of Care','Prioritization: rheumatology clinic','single_best_answer','A rheumatology clinic nurse receives four phone messages. Which client should the nurse call back first?','A client taking methotrexate who reports a sore throat, mouth sores, and a temperature of 101.5°F (38.6°C)|A client with osteoarthritis asking about a knee brace|A client with gout requesting a refill of allopurinol|A client with lupus asking about sunscreen','A','Fever with mouth sores in a client taking methotrexate may indicate bone marrow suppression (neutropenia) and serious infection, which requires urgent evaluation.','Integrated','Management of Care'),
('Set39-RN-2','Health Promotion and Maintenance','Postural orthostatic tachycardia syndrome','single_best_answer','A young adult with postural orthostatic tachycardia syndrome (POTS) asks how to manage symptoms. Which recommendations should the nurse include?','"Restrict fluids and salt."|"Increase fluid and salt intake as directed by your provider, wear compression garments, rise slowly, and gradually build up exercise, starting with recumbent activities."|"Stand still for long periods to adapt."|"Take hot baths to relax."','B','POTS involves an excessive heart rate increase when standing. Volume expansion, compression, and graded exercise improve tolerance. Heat and prolonged standing worsen symptoms.','Integrated','Fundamentals'),
('Set39-RN-3','Reduction of Risk Potential','ECG lead placement','single_best_answer','Where should the nurse place the V1 electrode for a 12-lead ECG?','Fifth intercostal space, left midclavicular line|Fourth intercostal space, right sternal border|Second intercostal space, left sternal border|Left midaxillary line at the level of V4','B','V1 is at the fourth intercostal space at the right sternal border, and V2 is at the same level on the left. Accurate placement prevents misleading tracings.','Integrated','Adult Health'),
('Set39-RN-4','Reduction of Risk Potential','Aspiration pneumonia','single_best_answer','A client who aspirated while lying upright develops pneumonia. In which area is the infiltrate most likely?','Left upper lobe|Right lower lobe|Left lingula|Both apices equally','B','The right main bronchus is wider, shorter, and more vertical, so aspirated material in an upright person tends to enter the right lower lobe.','Integrated','Adult Health'),
('Set39-RN-5','Reduction of Risk Potential','Pulse oximetry and skin pigmentation','single_best_answer','A client with dark skin has an SpO2 reading of 93% but has increasing shortness of breath and confusion. What should the nurse do?','Document the normal saturation and continue to monitor|Recognize that pulse oximeters can overestimate oxygen saturation in people with darker skin, assess the client''s overall condition, and anticipate an arterial blood gas|Remove the oximeter permanently|Assume the confusion is unrelated','B','Studies show pulse oximeters may overestimate saturation in people with darker skin pigmentation, which can hide hypoxemia. Clinical signs and ABGs guide decisions.','Integrated','Adult Health'),
('Set39-RN-6','Physiological Adaptation','Dysarthria vs aphasia','single_best_answer','After a stroke, a client understands and uses language correctly but has slurred speech that is hard to understand. How should the nurse document this?','Expressive aphasia|Dysarthria|Receptive aphasia|Global aphasia','B','Dysarthria is a motor speech disorder caused by weakness of the muscles used for speech. Aphasia is a language disorder affecting comprehension or expression. Speech therapy approaches differ.','Integrated','Adult Health'),
('Set39-RN-7','Physiological Adaptation','Frontal lobe tumor','single_best_answer','The family of a client with a newly diagnosed frontal lobe brain tumor reports recent personality changes. Which changes does the nurse expect?','Loss of hearing|Impulsiveness, poor judgment, disinhibition, and changes in personality|Visual field loss only|Loss of balance only','B','The frontal lobe governs executive function and personality. Occipital tumors affect vision, and cerebellar tumors affect coordination. Safety and family support are important.','Integrated','Adult Health'),
('Set39-RN-8','Physiological Adaptation','Hyperthyroidism in older adults','single_best_answer','An 81-year-old has weight loss, fatigue, new atrial fibrillation, and withdrawn behavior. Which condition should the nurse recognize as a possible cause?','Normal aging|Apathetic hyperthyroidism|Myxedema|Cushing''s syndrome','B','Older adults with hyperthyroidism may lack classic hyperactive symptoms and instead show apathy, weight loss, and atrial fibrillation. Thyroid testing is needed.','Integrated','Adult Health'),
('Set39-RN-9','Pharmacological and Parenteral Therapies','Perioperative stress-dose steroids','single_best_answer','A client who has taken prednisone 15 mg daily for 2 years is scheduled for major surgery. What does the nurse anticipate?','Stopping prednisone a week before surgery|Continuing the usual steroid and possibly receiving additional IV hydrocortisone (stress dosing) around surgery, as prescribed|Doubling the dose for a month after surgery|No change in steroids','B','Long-term steroid use suppresses the adrenal glands, which cannot increase cortisol during surgical stress. Stress dosing prevents adrenal crisis, which can cause refractory hypotension.','Integrated','Pharmacology'),
('Set39-RN-10','Reduction of Risk Potential','Esophagectomy','single_best_answer','A client had an esophagectomy with a gastric pull-up. Which nursing action is most important?','Keep the head of the bed flat|Keep the head of the bed elevated at least 30 degrees, and do not reposition or irrigate the NG tube without the surgeon''s order|Encourage a large meal on day 1|Reinsert the NG tube if it falls out','B','Elevation reduces reflux and aspiration. The NG tube lies across a fresh anastomosis, so blind manipulation risks a leak. Signs of a leak include fever, chest pain, and tachycardia.','Integrated','Adult Health'),
('Set39-RN-11','Health Promotion and Maintenance','Traveler''s diarrhea','single_best_answer','A client is traveling to an area with poor sanitation. Which advice helps prevent traveler''s diarrhea?','"Eat raw salads and drink tap water with ice."|"Boil it, cook it, peel it, or leave it. Drink bottled or treated water, avoid ice and street food, and wash hands often."|"Take antidiarrheal medicine every day."|"Avoid all fruit."','B','Food and water precautions and hand hygiene reduce exposure to enteric pathogens. Oral rehydration is the mainstay if diarrhea occurs.','Integrated','Fundamentals'),
('Set39-RN-12','Health Promotion and Maintenance','Skin cancer after transplant','single_best_answer','A client who had a kidney transplant 5 years ago asks why the provider recommends yearly skin checks. What is the nurse''s best response?','"Transplant recipients have lower cancer risk."|"Long-term immunosuppression greatly increases the risk of skin cancers, so daily sun protection and regular skin exams are important."|"Skin checks are only for people over 80."|"Sunscreen isn''t needed if you have darker skin."','B','Immunosuppressed clients have much higher rates of squamous cell carcinoma and other skin cancers. Prevention and early detection are key.','Integrated','Fundamentals'),
('Set39-RN-13','Reduction of Risk Potential','Carpal tunnel release','single_best_answer','A client had carpal tunnel release surgery today. Which instruction should the nurse include?','"Keep your hand below your waist."|"Elevate your hand above heart level, move your fingers often to prevent stiffness, and report increasing numbness, swelling, or color change."|"Lift heavy objects to strengthen your wrist right away."|"Keep the dressing wet."','B','Elevation reduces swelling, and finger movement prevents stiffness and tendon adhesions. Neurovascular changes may indicate tight dressings or complications.','Integrated','Adult Health'),
('Set39-RN-14','Physiological Adaptation','TRALI vs TACO','single_best_answer','Two hours into a plasma transfusion, a client develops acute respiratory distress, hypoxemia, fever, and hypotension. There is no JVD, and BNP is normal. What does the nurse suspect?','Transfusion-associated circulatory overload (TACO)|Transfusion-related acute lung injury (TRALI)|A mild allergic reaction|Iron overload','B','TRALI is noncardiogenic pulmonary edema, often with hypotension and fever. TACO typically causes hypertension, JVD, and an elevated BNP. For both, the transfusion is stopped and respiratory support given, but diuretics help TACO, not TRALI.','Integrated','Adult Health'),
('Set39-RN-15','Health Promotion and Maintenance','Basal cell carcinoma','single_best_answer','Which lesion description is most typical of basal cell carcinoma?','An asymmetric mole with multiple colors|A pearly or waxy bump with rolled edges and small visible blood vessels, sometimes with a central ulcer|A flat, uniform brown freckle|A fluid-filled blister','B','Basal cell carcinoma is the most common skin cancer. It rarely spreads but can invade locally. Melanoma follows the ABCDE warning signs.','Integrated','Fundamentals'),
('Set39-RN-16','Safety and Infection Control','Post-vaccination observation','single_best_answer','Why should the nurse have clients remain in the clinic for about 15 minutes after receiving a vaccine?','To collect payment|To observe for fainting and rare immediate allergic reactions such as anaphylaxis, with emergency medications available|To check antibody levels|It is not necessary','B','Syncope, especially in adolescents, and anaphylaxis usually occur shortly after vaccination. A longer observation period (30 minutes) is used for clients with prior allergic reactions.','Integrated','Safety & Infection Control'),
('Set39-RN-17','Psychosocial Integrity','Positive reinforcement','single_best_answer','A child with ADHD on a pediatric unit earns a sticker each time they complete a task, and stickers can be traded for extra playtime. What behavioral approach is this?','Punishment|Positive reinforcement (token economy)|Negative reinforcement|Extinction','B','Rewarding desired behavior increases its frequency. Token systems are effective when rewards are immediate, consistent, and meaningful to the child.','Integrated','Mental Health'),
('Set39-RN-18','Reduction of Risk Potential','Bladder care with epidural','single_best_answer','A laboring client has had an epidural for 5 hours. Which assessment is especially important?','Pupil response|Bladder distention, with catheterization as needed, because the epidural can reduce the sensation and urge to void|Hearing|Deep tendon reflexes in the arms','B','A full bladder can slow fetal descent, increase discomfort, and contribute to postpartum hemorrhage. The bladder is assessed regularly and emptied as needed.','Integrated','Adult Health'),
('Set39-RN-19','Basic Care and Comfort','Cleft palate feeding','single_best_answer','An infant with an unrepaired cleft palate is having difficulty feeding. Which technique should the nurse teach the parents?','"Feed the baby lying flat."|"Use a specialized bottle and nipple for cleft palate, feed the baby in an upright position, and burp frequently because the baby swallows extra air."|"Feed only once every 6 hours."|"Use a regular bottle with a large hole cut in the nipple." Case study (use for RN Questions 20–25). A 17-year-old with sickle cell disease (HbSS) was admitted 2 days ago with a vaso-occlusive crisis causing back and leg pain. The client has a morphine PCA and IV fluids. The incentive spirometer at the bedside has not been used. Nurses'' notes, 0400: New right-sided chest pain that worsens with breathing, and a cough. Breathing is shallow, and the client is guarding the chest. Crackles in the right lower lobe. Drowsy but arousable. Vital signs: T 102.2°F (39°C), HR 124/min, RR 30/min, BP 112/66 mm Hg, SpO2 89% on room air. Laboratory and imaging results: hemoglobin 6.4 g/dL (baseline 8.5), WBC 19,000/mm³, reticulocytes elevated. Chest x-ray shows a new right lower lobe infiltrate.','B','A cleft palate prevents effective suction. Special feeders, upright positioning, and frequent burping reduce choking, fatigue, and air swallowing. Feedings should take no longer than about 30 minutes.','Integrated','Adult Health'),
('Set40-RN-1','Management of Care','Prioritization: urgent care','single_best_answer','The nurse in an urgent care center is triaging four clients who just arrived. Which client should the nurse care for first?','A client who splashed drain cleaner into one eye 5 minutes ago and is in severe pain|A client with an ankle sprain from basketball|A client with a sore throat and a temperature of 100.4°F (38°C)|A client requesting a tetanus booster after a clean scrape','A','Alkaline chemical eye injuries penetrate quickly and can cause permanent vision loss. Immediate, prolonged irrigation is required before any other assessment.','Integrated','Management of Care'),
('Set40-RN-2','Reduction of Risk Potential','Premature ventricular contractions','single_best_answer','A client on telemetry has new, frequent PVCs. The client is alert with stable BP. Which labs should the nurse check first?','Serum amylase and lipase|Serum potassium and magnesium|Hemoglobin A1C|Uric acid','B','Hypokalemia and hypomagnesemia increase myocardial irritability and PVCs. Other triggers include hypoxia, ischemia, caffeine, and certain drugs.','Integrated','Adult Health'),
('Set40-RN-3','Health Promotion and Maintenance','Sclerotherapy','single_best_answer','A client had sclerotherapy for varicose veins today. Which instruction should the nurse include?','"Avoid walking for a week."|"Wear the prescribed compression stockings, walk regularly, and avoid prolonged sitting, hot baths, and sun exposure to the treated areas for the time directed."|"Apply heat packs to the injection sites."|"Sit with your legs crossed."','B','Compression and walking promote venous flow and help the treated veins close. Heat and prolonged sitting increase the risk of clots.','Integrated','Fundamentals'),
('Set40-RN-4','Basic Care and Comfort','Airway clearance in cystic fibrosis','single_best_answer','An adolescent with cystic fibrosis uses a high-frequency chest wall oscillation vest. When should the nurse recommend the treatment?','Right after eating a large meal|Before meals or at least 1–2 hours after eating, usually after bronchodilator inhalation, followed by hypertonic saline or dornase alfa as prescribed|Only when the client has a fever|Once a week','B','Airway clearance on a full stomach can cause vomiting. Bronchodilators open the airways and mucolytics thin secretions, which improves clearance. Regular daily therapy prevents mucus plugging and infection.','Integrated','Adult Health'),
('Set40-RN-5','Reduction of Risk Potential','Central line insertion','single_best_answer','A subclavian central venous catheter was just placed. Which action is required before the nurse uses the line?','Flush it with a large volume of saline immediately|Confirm tip placement and rule out pneumothorax with a chest x-ray (or other approved method), and assess breath sounds and respiratory status|Start vasopressors right away|Remove the sterile dressing','B','Subclavian and internal jugular insertions can puncture the lung. Confirming placement and checking for pneumothorax prevents harm from infusing into the wrong place.','Integrated','Adult Health'),
('Set40-RN-6','Safety and Infection Control','Meningococcal exposure','single_best_answer','A college student is diagnosed with meningococcal meningitis. The roommate asks what to do. What is the nurse''s best response?','"You don''t need to do anything."|"Close contacts like roommates should receive preventive antibiotics as soon as possible, and should watch for fever, headache, or stiff neck."|"You need the live vaccine instead."|"Wait until you have symptoms."','B','Chemoprophylaxis with rifampin, ciprofloxacin, or ceftriaxone for close contacts reduces the risk of secondary cases. Healthcare workers need prophylaxis only after unprotected exposure to respiratory secretions.','Integrated','Safety & Infection Control'),
('Set40-RN-7','Physiological Adaptation','Wernicke encephalopathy','single_best_answer','A malnourished client with alcohol use disorder is confused, has an unsteady gait, and has abnormal eye movements (nystagmus). What does the nurse anticipate?','IV dextrose first, then thiamine the next day|IV thiamine promptly, before or with glucose|Lorazepam alone|Vitamin C supplements','B','Confusion, ataxia, and ophthalmoplegia suggest Wernicke encephalopathy, which is caused by thiamine deficiency. Prompt thiamine can reverse symptoms and prevent permanent Korsakoff syndrome.','Integrated','Adult Health'),
('Set40-RN-8','Pharmacological and Parenteral Therapies','Sulfonylureas in older adults','single_best_answer','An 84-year-old with type 2 diabetes and reduced kidney function is prescribed glyburide. What should the nurse do?','Administer it as prescribed|Clarify the prescription, because glyburide carries a high risk of prolonged hypoglycemia in older adults, especially with kidney impairment|Double the dose|Give it at bedtime without food','B','Glyburide is on the Beers Criteria list because of prolonged hypoglycemia risk. Safer options are chosen, and glucose goals are individualized.','Integrated','Pharmacology'),
('Set40-RN-9','Pharmacological and Parenteral Therapies','Long-term PPI use','single_best_answer','A client has taken omeprazole daily for 8 years. Which potential long-term effects should the nurse discuss with the provider?','Improved bone density|Increased risk of fractures, low magnesium, low vitamin B12, and|difficile infection|Decreased infection risk|Hyperkalemia','B','Long-term acid suppression affects nutrient absorption and gut flora. Periodic review determines whether continued therapy is needed or the dose can be reduced.','Integrated','Pharmacology'),
('Set40-RN-10','Reduction of Risk Potential','Dry weight in hemodialysis','single_best_answer','A client receiving hemodialysis asks what "dry weight" means. What is the nurse''s best response?','"Your weight after a big meal."|"Your target weight after dialysis, when excess fluid has been removed and you have no swelling, without becoming too low in fluid."|"Your weight before dialysis."|"Your weight when you were a child."','B','Dry weight guides how much fluid is removed each session. Weight gain between sessions reflects fluid intake, and large gains increase the risk of hypotension during dialysis and of heart strain.','Integrated','Adult Health'),
('Set40-RN-11','Physiological Adaptation','Osteomalacia','single_best_answer','A homebound older adult with little sun exposure has diffuse bone pain, muscle weakness, and a low vitamin D level. Which condition does the nurse suspect?','Gout|Osteomalacia|Osteoarthritis|Fibromyalgia','B','Vitamin D deficiency impairs bone mineralization, which softens bones and increases fracture and fall risk. Treatment is vitamin D and calcium replacement.','Integrated','Adult Health'),
('Set40-RN-12','Physiological Adaptation','Childhood leukemia','single_best_answer','A 5-year-old has had increasing tiredness, pallor, frequent nosebleeds, easy bruising, and bone pain for several weeks. Which condition should the nurse recognize as a concern?','Iron deficiency only|Acute leukemia|Growing pains|Seasonal allergies','B','Bone marrow infiltration crowds out normal cells, causing anemia, low platelets, and bone pain. A CBC with differential is the first step in evaluation.','Integrated','Adult Health'),
('Set40-RN-13','Health Promotion and Maintenance','Ovarian cancer warning signs','single_best_answer','A 58-year-old reports persistent bloating, feeling full quickly, and pelvic discomfort almost daily for 6 weeks. What should the nurse recommend?','"These are normal digestive changes with age."|"Schedule an evaluation soon, because persistent symptoms like these can be early signs of ovarian cancer."|"Take antacids and wait a few months."|"Only worry if you have vaginal bleeding."','B','Ovarian cancer often causes vague, persistent symptoms. There is no reliable screening test for average-risk clients, so symptoms lasting more than 2–3 weeks warrant evaluation.','Integrated','Fundamentals'),
('Set40-RN-14','Safety and Infection Control','Rabies post-exposure prophylaxis','single_best_answer','A client was bitten by a bat that flew into the house and has never received a rabies vaccine. Which treatment does the nurse anticipate?','No treatment unless symptoms develop|Thorough wound washing, human rabies immune globulin at the wound site, and a series of rabies vaccine doses|Antibiotics only|A single tetanus shot only','B','Rabies is nearly always fatal once symptoms appear, and bat bites can be tiny. Post-exposure prophylaxis given promptly is highly effective.','Integrated','Safety & Infection Control'),
('Set40-RN-15','Psychosocial Integrity','Dissociative amnesia','single_best_answer','After a traumatic event, a client cannot remember important personal information about the event and appears detached. Which nursing approach is most appropriate?','Force the client to recall the event in detail immediately|Provide a safe, calm environment, use grounding techniques, avoid pushing for memories, and support referral for trauma-focused therapy|Tell the client they are faking|Leave the client alone for long periods','B','Dissociation is a protective response to overwhelming trauma. Safety and gradual processing in therapy help, and pressuring recall can retraumatize the client.','Integrated','Mental Health'),
('Set40-RN-16','Psychosocial Integrity','Sexual assault care','single_best_answer','A client arrives at the emergency department after a sexual assault 3 hours ago. Which nursing action is most appropriate?','Encourage the client to shower before the exam|Provide a private, supportive environment, explain options, obtain consent for each step, and involve a trained sexual assault nurse examiner (SANE) if available, while preserving evidence|Question the client about why they were in that situation|Discard the client''s clothing','B','Trauma-informed care supports the client''s control and safety. Evidence is preserved (no showering, clothing bagged in paper) if the client consents. Care includes STI and pregnancy prophylaxis options and advocacy resources.','Integrated','Mental Health'),
('Set40-RN-17','Pharmacological and Parenteral Therapies','Intrapartum GBS prophylaxis','single_best_answer','A GBS-positive client in active labor asks why IV penicillin is being started now. What is the nurse''s best response?','"It treats a urinary infection."|"Giving antibiotics at least 4 hours before birth greatly reduces the chance of your baby developing a serious GBS infection."|"It will speed up your labor."|"It''s only needed after the baby is born."','B','Adequate intrapartum prophylaxis (at least 4 hours before delivery) prevents early-onset GBS disease in newborns. The newborn is observed after birth according to risk.','Integrated','Pharmacology'),
('Set40-RN-18','Reduction of Risk Potential','Developmental hip dysplasia screening','single_best_answer','During a newborn exam, the provider feels a "clunk" as the hip is gently moved outward and forward. How should the nurse interpret this finding?','A normal finding in all newborns|A positive Ortolani maneuver, suggesting developmental dysplasia of the hip, which needs follow-up|A sign of a clavicle fracture|A sign of hypotonia','B','The Ortolani and Barlow maneuvers screen for hip instability. Unequal thigh folds and limited abduction are other signs. Early treatment, such as a Pavlik harness, gives the best results.','Integrated','Adult Health'),
('Set40-RN-19','Physiological Adaptation','Pediatric growth plate injury','single_best_answer','A 10-year-old has wrist pain and swelling after a fall, and the x-ray shows a fracture through the growth plate. Why is follow-up especially important?','Growth plate fractures heal slower than adult fractures in all cases|Injuries to the growth plate can disrupt bone growth, causing limb length differences or deformity, so orthopedic follow-up is needed|Children don''t need casts|Growth plate injuries never need treatment Case study (use for RN Questions 20–25). A 52-year-old client who takes sertraline 150 mg daily and trazodone at bedtime was admitted with MRSA pneumonia. IV linezolid was started 24 hours ago. The client has also received tramadol for pleuritic pain and IV ondansetron for nausea. Nurses'' notes, 1400: Agitated, restless, and intermittently confused. Profuse sweating. Tremor of both hands. Hyperactive reflexes in the legs with sustained ankle clonus. Pupils dilated. Three episodes of diarrhea since noon. Muscle tone increased in the legs more than the arms. Vital signs: T 103.1°F (39.5°C), HR 132/min, BP 168/98 mm Hg, RR 24/min, SpO2 95% on 2 L/min. Laboratory results: CK 1,900 units/L (mildly elevated), creatinine 1.1 mg/dL, WBC 13,800/mm³.','B','The growth plate (physis) is the weakest part of a child''s bone. Salter-Harris classification guides treatment, and some injuries need surgery to protect growth.','Integrated','Adult Health')
) x(src,client_need,topic,item_type,stem,opts,keys,rationale,body_system,discipline) loop
 qid:=md5('rnmaster-'||lower(r.src))::uuid; qvid:=md5('rnmaster-v-'||lower(r.src))::uuid;
 insert into public.questions(id,slug,lifecycle_status,current_version) values(qid,'rnmaster-'||lower(r.src),'pilot',1) on conflict(slug) do update set updated_at=now() returning id into qid;
 keyarr:=string_to_array(r.keys,',');
 insert into public.question_versions(id,question_id,version,stem,item_type,exam_tracks,subject,topic,client_need,difficulty,rationale_correct,rationale_distractors,memory_rule,source_note,validation_status,professional_role_focus,track_rationale,body_system,discipline,source_id,response_config,scoring_method)
 values(qvid,qid,1,r.stem,r.item_type,array['rn'],r.client_need,r.topic,r.client_need,'medium',r.rationale,'Each distractor must be evaluated against the clinical task and source rationale.','Identify the task, interpret the cues, and compare every option with the safest evidence-based RN response.','User-provided NCLEX-RN Master Edition; loaded as PILOT pending clinical/editorial validation. Not human or psychometrically validated.','pilot','Entry-level RN clinical judgment.','NCLEX-RN',r.body_system,r.discipline,'RNMaster-'||r.src,'{}'::jsonb,case when r.item_type='multiple_response' then 'plus_minus' else 'zero_one' end)
 on conflict(question_id,version) do update set stem=excluded.stem,item_type=excluded.item_type,source_id=excluded.source_id,validation_status='pilot' returning id into qvid;
 delete from public.question_options where question_version_id=qvid; n:=0;
 for optrec in select unnest(string_to_array(r.opts,'|')) as txt loop n:=n+1; insert into public.question_options(question_version_id,option_key,option_text,is_correct,rationale,display_order) values(qvid,chr(96+n),optrec.txt,(upper(chr(96+n))=any(keyarr)),case when upper(chr(96+n))=any(keyarr) then r.rationale else null end,n); end loop;
 select count(*) filter(where is_correct) into kc from public.question_options where question_version_id=qvid;
 if (r.item_type='single_best_answer' and kc<>1) or (r.item_type='multiple_response' and kc<2) then raise exception 'Key integrity failed %',r.src; end if;
 update public.question_versions set key_consistency_status='pass',key_consistency_checked_at=now(),key_consistency_notes='Source key/options passed deterministic consistency validation; clinical review pending.' where id=qvid;
end loop;
end $$;
commit;